Here's a command-line calculator with error handling that loops until you quit:

```python
def add(a, b): return a + b
def sub(a, b): return a - b
def mul(a, b): return a * b
def div(a, b):
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

OPS = {"+": add, "-": sub, "*": mul, "/": div}

def main():
    print("Simple Calculator (type 'q' to quit)")
    while True:
        raw = input("\nEnter expression (e.g. 5 + 3): ").strip()
        if raw.lower() == "q":
            break
        try:
            a, op, b = raw.split()
            result = OPS[op](float(a), float(b))
            print(f"= {result}")
        except KeyError:
            print("Unknown operator. Use + - * /")
        except ValueError as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

Run with `python calculator.py`.

A CLI to-do app that saves tasks to a JSON file:

```python
import json
from pathlib import Path

FILE = Path("todos.json")

def load():
    return json.loads(FILE.read_text()) if FILE.exists() else []

def save(todos):
    FILE.write_text(json.dumps(todos, indent=2))

def show(todos):
    if not todos:
        print("Nothing to do!")
    for i, t in enumerate(todos, 1):
        print(f"{i}. [{'x' if t['done'] else ' '}] {t['title']}")

def main():
    todos = load()
    while True:
        cmd = input("\n(a)dd (d)one (r)emove (l)ist (q)uit > ").lower()
        if cmd == "a":
            todos.append({"title": input("Task: "), "done": False})
        elif cmd == "d":
            show(todos); todos[int(input("Number: ")) - 1]["done"] = True
        elif cmd == "r":
            show(todos); todos.pop(int(input("Number: ")) - 1)
        elif cmd == "l":
            show(todos)
        elif cmd == "q":
            break
        save(todos)

if __name__ == "__main__":
    main()
```

