A small CRUD API for a `books` resource (in-memory). Install: `pip install flask`.

```python
from flask import Flask, jsonify, request, abort

app = Flask(__name__)
books = {1: {"id": 1, "title": "Dune", "author": "Frank Herbert"}}
next_id = 2

@app.get("/books")
def list_books():
    return jsonify(list(books.values()))

@app.get("/books/<int:book_id>")
def get_book(book_id):
    return jsonify(books.get(book_id) or abort(404))

@app.post("/books")
def create_book():
    global next_id
    data = request.get_json(silent=True) or {}
    if "title" not in data or "author" not in data:
        abort(400, "title and author required")
    book = {"id": next_id, **{k: data[k] for k in ("title", "author")}}
    books[next_id] = book
    next_id += 1
    return jsonify(book), 201

@app.put("/books/<int:book_id>")
def update_book(book_id):
    if book_id not in books:
        abort(404)
    books[book_id].update(request.get_json() or {})
    return jsonify(books[book_id])

@app.delete("/books/<int:book_id>")
def delete_book(book_id):
    books.pop(book_id, None)
    return "", 204

if __name__ == "__main__":
    app.run(debug=True)
```

Test: `curl -X POST localhost:5000/books -H "Content-Type: application/json" -d '{"title":"Emma","author":"Austen"}'`

