Both handle asynchronous work. `async/await` is syntax built on top of Promises that reads like synchronous code.

```javascript
// Promise chain
fetch("/user")
  .then(r => r.json())
  .then(u => fetch(`/posts?user=${u.id}`))
  .then(r => r.json())
  .catch(console.error);

// async/await (same thing)
async function load() {
  try {
    const u = await (await fetch("/user")).json();
    return await (await fetch(`/posts?user=${u.id}`)).json();
  } catch (e) { console.error(e); }
}

// Run in parallel, not sequentially
const [a, b] = await Promise.all([fetch("/a"), fetch("/b")]);
```

Useful helpers: `Promise.all` (all succeed), `Promise.allSettled` (never rejects), `Promise.race` (first to finish), `Promise.any` (first to succeed).

```javascript
function quickSort(arr) {
  if (arr.length <= 1) return arr;
  const pivot = arr[Math.floor(arr.length / 2)];
  const left = arr.filter(x => x < pivot);
  const mid = arr.filter(x => x === pivot);
  const right = arr.filter(x => x > pivot);
  return [...quickSort(left), ...mid, ...quickSort(right)];
}

console.log(quickSort([5, 3, 8, 1, 9, 2]));  // [1,2,3,5,8,9]
```

Average O(n log n), worst case O(n²) with bad pivots. This version is readable but uses extra memory; in-place partitioning (Lomuto/Hoare) avoids that.

