#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *push_front(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) { perror("malloc"); exit(1); }
    n->value = value;
    n->next = head;
    return n;
}

void print_list(const Node *head) {
    for (; head; head = head->next) printf("%d -> ", head->value);
    puts("NULL");
}

void free_list(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) list = push_front(list, i);
    print_list(list);   // 5 -> 4 -> 3 -> 2 -> 1 -> NULL
    free_list(list);
    return 0;
}
