The compiler forces you to handle every alternative, so adding a new shape causes a compile error wherever a case is missing.

C++17 fold expressions expand a parameter pack with an operator, avoiding recursion.

```cpp
#include <iostream>
#include <type_traits>

template <typename... Args>
constexpr auto sum(Args... args) {
    return (args + ... + 0);         // binary left fold with initial value 0
}

template <typename... Args>
void print_all(const Args&... args) {
    ((std::cout << args << ' '), ...);   // comma fold
    std::cout << '\n';
}

// Compile-time check that every argument is arithmetic
template <typename... Args>
constexpr bool all_arithmetic = (std::is_arithmetic_v<Args> && ...);

static_assert(all_arithmetic<int, double, float>);
static_assert(sum(1, 2, 3) == 6);

int main() {
    print_all("a", 1, 2.5);
    std::cout << sum(1.5, 2.5, 3) << '\n';   // 7
}
```

`(args + ... + 0)` is a unary-binary fold. It expands to `((a1 + a2) + a3) + 0`.

An iterative segment tree gives O(log n) range queries and point updates.

```cpp
#include <iostream>
#include <vector>

class SegmentTree {
public:
    explicit SegmentTree(const std::vector<long long>& a)
        : n_(a.size()), t_(2 * n_) {
        for (size_t i = 0; i < n_; ++i) t_[n_ + i] = a[i];
        for (size_t i = n_ - 1; i > 0; --i) t_[i] = t_[2 * i] + t_[2 * i + 1];
    }

    void update(size_t pos, long long value) {
        for (t_[pos += n_] = value; pos > 1; pos >>= 1)
            t_[pos >> 1] = t_[pos] + t_[pos ^ 1];
    }

    // sum over [l, r)
    long long query(size_t l, size_t r) const {
        long long res = 0;
        for (l += n_, r += n_; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res += t_[l++];
            if (r & 1) res += t_[--r];
        }
        return res;
    }

private:
    size_t n_;
    std::vector<long long> t_;
};

int main() {
    SegmentTree st({1, 3, 5, 7, 9, 11});
    std::cout << st.query(1, 4) << '\n';   // 3+5+7 = 15
    st.update(2, 10);
    std::cout << st.query(1, 4) << '\n';   // 3+10+7 = 20
}
```

The bottom-up layout uses `2n` memory and works for any `n`. Swap `+` for `min`/`max`/`gcd` to answer other associative range queries.

```cpp
#include <numeric>
#include <vector>

class DSU {
public:
    explicit DSU(int n) : parent_(n), rank_(n, 0), components_(n) {
        std::iota(parent_.begin(), parent_.end(), 0);
    }

    int find(int x) {
        if (parent_[x] != x) parent_[x] = find(parent_[x]);   // path compression
        return parent_[x];
    }

    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (rank_[a] < rank_[b]) std::swap(a, b);             // union by rank
        parent_[b] = a;
        if (rank_[a] == rank_[b]) ++rank_[a];
        --components_;
        return true;
    }

    int components() const { return components_; }

private:
    std::vector<int> parent_, rank_;
    int components_;
};

// Kruskal-style cycle detection example
bool has_cycle(int n, const std::vector<std::pair<int,int>>& edges) {
    DSU dsu(n);
    for (auto [u, v] : edges)
        if (!dsu.unite(u, v)) return true;
    return false;
}
```

With both optimizations, operations run in nearly O(1) amortized time (inverse Ackermann).

`IAsyncEnumerable<T>` lets you stream results as they arrive instead of buffering everything.

```csharp
using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;

public static class Feed
{
    public static async IAsyncEnumerable<int> Ticks(
        int count,
        [EnumeratorCancellation] CancellationToken ct = default)
    {
        for (int i = 1; i <= count; i++)
        {
            ct.ThrowIfCancellationRequested();
            await Task.Delay(200, ct);     // simulated I/O
            yield return i;
        }
    }
}

public static class Program
{
    public static async Task Main()
    {
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        try
        {
            await foreach (var tick in Feed.Ticks(10).WithCancellation(cts.Token))
                Console.WriteLine($"Got {tick}");
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine("Cancelled.");
        }
    }
}
```

`[EnumeratorCancellation]` ensures the token passed to `WithCancellation` flows into the iterator. Without it the cancellation token is silently ignored.

Modern C# lets you model data immutably and dispatch on its shape concisely.

```csharp
using System;

public abstract record Expr;
public sealed record Num(double Value) : Expr;
public sealed record Add(Expr Left, Expr Right) : Expr;
public sealed record Mul(Expr Left, Expr Right) : Expr;
public sealed record Neg(Expr Operand) : Expr;

public static class Evaluator
{
    public static double Eval(Expr e) => e switch
    {
        Num n                  => n.Value,
        Add(var l, var r)      => Eval(l) + Eval(r),
        Mul(Num { Value: 0 }, _) => 0,              // constant pattern on nested record
        Mul(var l, var r)      => Eval(l) * Eval(r),
        Neg(var x)             => -Eval(x),
        _ => throw new ArgumentException("Unknown expression")
    };
}

public static class Demo
{
    public static void Main()
    {
        var e = new Add(new Num(2), new Mul(new Num(3), new Neg(new Num(4))));
        Console.WriteLine(Evaluator.Eval(e));   // 2 + 3 * -4 = -10

        var copy = e with { Left = new Num(5) }; // non-destructive update
        Console.WriteLine(copy);
    }
}
```

Records give value equality and `with` expressions for immutable updates. Property patterns like `Num { Value: 0 }` match nested structure directly.

