```html
<canvas id="c" style="width:100%;height:100vh;display:block;background:#000"></canvas>
<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
let w, h, particles = [];

function resize() {
  const dpr = window.devicePixelRatio || 1;          // crisp on retina
  w = canvas.clientWidth; h = canvas.clientHeight;
  canvas.width = w * dpr; canvas.height = h * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}

function spawn(n) {
  particles = Array.from({ length: n }, () => ({
    x: Math.random() * w, y: Math.random() * h,
    vx: (Math.random() - 0.5) * 1.5, vy: (Math.random() - 0.5) * 1.5,
  }));
}

let mouse = { x: -9999, y: -9999 };
canvas.addEventListener("pointermove", e => {
  const r = canvas.getBoundingClientRect();
  mouse = { x: e.clientX - r.left, y: e.clientY - r.top };
});

function frame() {
  ctx.clearRect(0, 0, w, h);
  for (const p of particles) {
    const dx = p.x - mouse.x, dy = p.y - mouse.y;
    const d2 = dx * dx + dy * dy;
    if (d2 < 10000) { p.vx += dx / 500; p.vy += dy / 500; }   // repel from pointer
    p.x += p.vx; p.y += p.vy;
    if (p.x < 0 || p.x > w) p.vx *= -1;
    if (p.y < 0 || p.y > h) p.vy *= -1;
    ctx.fillStyle = "#6cf";
    ctx.fillRect(p.x, p.y, 2, 2);
  }
  requestAnimationFrame(frame);
}

window.addEventListener("resize", () => { resize(); spawn(150); });
resize(); spawn(150); frame();
</script>
```

Scaling by `devicePixelRatio` keeps the canvas sharp on high-DPI screens. The animation loop uses `requestAnimationFrame`, which pauses automatically in background tabs.

