A single file with no dependencies. Columns and cards are saved to `localStorage` and survive reloads.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban</title>
<style>
  body { font-family: system-ui, sans-serif; background: #f4f5f7; margin: 0; padding: 1.5rem; }
  .board { display: grid; grid-template-columns: repeat(3, minmax(220px, 1fr)); gap: 1rem; }
  .col { background: #ebecf0; border-radius: 8px; padding: .75rem; min-height: 300px; }
  .col.over { outline: 2px dashed #4c9aff; }
  .col h2 { font-size: 1rem; margin: 0 0 .5rem; }
  .card { background: #fff; padding: .6rem .8rem; border-radius: 6px; margin-bottom: .5rem;
          box-shadow: 0 1px 2px rgb(0 0 0 / .15); cursor: grab; }
  .card.dragging { opacity: .4; }
  .add { width: 100%; padding: .4rem; margin-top: .3rem; }
</style>
</head>
<body>
<div class="board" id="board"></div>

<script>
const KEY = "kanban-v1";
const state = JSON.parse(localStorage.getItem(KEY)) ?? {
  todo: ["Design logo"], doing: ["Write docs"], done: ["Set up repo"]
};
const titles = { todo: "To do", doing: "In progress", done: "Done" };
let dragged = null;   // { card, from }

function save() { localStorage.setItem(KEY, JSON.stringify(state)); }

function render() {
  const board = document.getElementById("board");
  board.replaceChildren(...Object.keys(state).map(col => {
    const el = document.createElement("section");
    el.className = "col";
    el.dataset.col = col;
    const h = document.createElement("h2");
    h.textContent = `${titles[col]} (${state[col].length})`;
    el.append(h, ...state[col].map((text, i) => cardEl(col, text, i)));
    const add = document.createElement("button");
    add.className = "add";
    add.textContent = "+ Add card";
    add.onclick = () => {
      const text = prompt("Card text");
      if (text?.trim()) { state[col].push(text.trim()); save(); render(); }
    };
    el.append(add);
    el.addEventListener("dragover", e => { e.preventDefault(); el.classList.add("over"); });
    el.addEventListener("dragleave", () => el.classList.remove("over"));
    el.addEventListener("drop", e => {
      e.preventDefault();
      el.classList.remove("over");
      if (!dragged) return;
      state[dragged.from].splice(dragged.index, 1);
      state[col].push(dragged.text);
      dragged = null;
      save(); render();
    });
    return el;
  }));
}

function cardEl(col, text, index) {
  const c = document.createElement("div");
  c.className = "card";
  c.draggable = true;
  c.textContent = text;
  c.addEventListener("dragstart", () => {
    dragged = { from: col, index, text };
    c.classList.add("dragging");
  });
  c.addEventListener("dragend", () => c.classList.remove("dragging"));
  return c;
}

render();
</script>
</body>
</html>
```

The native HTML5 drag-and-drop API needs no library. `textContent` is used instead of `innerHTML`, so card text can't inject markup.

Writes Markdown on the left and renders it on the right. The renderer escapes HTML first, so pasted `<script>` tags are shown as text.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Markdown Editor</title>
<style>
  body { margin: 0; font-family: system-ui; height: 100vh; display: flex; flex-direction: column; }
  .panes { flex: 1; display: grid; grid-template-columns: 1fr 1fr; min-height: 0; }
  textarea { border: 0; padding: 1rem; font: 14px/1.5 ui-monospace, monospace; resize: none; border-right: 1px solid #ddd; }
  #preview { padding: 1rem; overflow: auto; }
  pre { background: #f6f8fa; padding: .75rem; overflow-x: auto; }
  code { background: #f6f8fa; padding: 0 .2rem; }
</style>
</head>
<body>
<div class="panes">
  <textarea id="src" spellcheck="false">
# Hello

Some **bold** text, a [link](https://example.com), and `inline code`.

- item one
- item two

```js
console.log("hi");
```
  </textarea>
  <div id="preview"></div>
</div>

<script>
const escape = s => s.replace(/[&<>"']/g, c =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// Inline rules run after escaping, so user input can never create tags except ours.
function inline(s) {
  return s
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
             '<a href="$2" rel="noopener noreferrer">$1</a>');
}

function render(md) {
  const out = [];
  let inCode = false, inList = false;
  for (const raw of md.split("\n")) {
    if (raw.startsWith("```")) {
      out.push(inCode ? "</code></pre>" : "<pre><code>");
      inCode = !inCode;
      continue;
    }
    if (inCode) { out.push(escape(raw) + "\n"); continue; }
    const line = escape(raw);
    const h = line.match(/^(#{1,6})\s+(.*)/);
    const li = line.match(/^[-*]\s+(.*)/);
    if (li && !inList) { out.push("<ul>"); inList = true; }
    if (!li && inList) { out.push("</ul>"); inList = false; }
    if (h) out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`);
    else if (li) out.push(`<li>${inline(li[1])}</li>`);
    else if (line.trim()) out.push(`<p>${inline(line)}</p>`);
  }
  if (inList) out.push("</ul>");
  return out.join("\n");
}

const src = document.getElementById("src");
const preview = document.getElementById("preview");
src.addEventListener("input", () => preview.innerHTML = render(src.value));
preview.innerHTML = render(src.value);
</script>
</body>
</html>
```

The security rule is that escaping comes first and Markdown rules are applied afterward. Reversing the order is a common XSS bug. For production, use a maintained parser such as `marked` together with `DOMPurify`.

Follows the WAI-ARIA Tabs pattern: arrow keys move between tabs, Home and End jump to the ends, and only the active tab is in the tab order.

```html
<div class="tabs">
  <div role="tablist" aria-label="Account settings">
    <button role="tab" id="t-profile" aria-controls="p-profile" aria-selected="true" tabindex="0">Profile</button>
    <button role="tab" id="t-billing" aria-controls="p-billing" aria-selected="false" tabindex="-1">Billing</button>
    <button role="tab" id="t-security" aria-controls="p-security" aria-selected="false" tabindex="-1">Security</button>
  </div>
  <section role="tabpanel" id="p-profile" aria-labelledby="t-profile">Profile content</section>
  <section role="tabpanel" id="p-billing" aria-labelledby="t-billing" hidden>Billing content</section>
  <section role="tabpanel" id="p-security" aria-labelledby="t-security" hidden>Security content</section>
</div>

<style>
  [role="tab"] { padding: .5rem 1rem; border: 0; background: none; cursor: pointer; border-bottom: 2px solid transparent; }
  [role="tab"][aria-selected="true"] { border-bottom-color: #2563eb; font-weight: 600; }
  [role="tab"]:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }
  [role="tabpanel"] { padding: 1rem; }
</style>

<script>
const tablist = document.querySelector('[role="tablist"]');
const tabs = [...tablist.querySelectorAll('[role="tab"]')];

function select(tab, focus = true) {
  for (const t of tabs) {
    const on = t === tab;
    t.setAttribute("aria-selected", on);
    t.tabIndex = on ? 0 : -1;
    document.getElementById(t.getAttribute("aria-controls")).hidden = !on;
  }
  if (focus) tab.focus();
}

tablist.addEventListener("click", e => {
  const tab = e.target.closest('[role="tab"]');
  if (tab) select(tab, false);
});

tablist.addEventListener("keydown", e => {
  const i = tabs.indexOf(document.activeElement);
  if (i < 0) return;
  const map = {
    ArrowRight: (i + 1) % tabs.length,
    ArrowLeft: (i - 1 + tabs.length) % tabs.length,
    Home: 0,
    End: tabs.length - 1,
  };
  if (e.key in map) { e.preventDefault(); select(tabs[map[e.key]]); }
});
</script>
```

Only the active tab gets `tabindex="0"`, which keeps the tab order short. Screen readers announce the selected state through `aria-selected`.

Press Ctrl+K (or Cmd+K) to open a searchable list of actions. Matching is fuzzy: the query letters must appear in order, not next to each other.

```html
<style>
  #palette { position: fixed; inset: 0; background: rgb(0 0 0 / .4); display: none; align-items: flex-start; justify-content: center; padding-top: 15vh; }
  #palette.open { display: flex; }
  .box { background: #fff; width: min(560px, 90vw); border-radius: 10px; overflow: hidden; font-family: system-ui; }
  #q { width: 100%; box-sizing: border-box; padding: 1rem; font-size: 1rem; border: 0; border-bottom: 1px solid #ddd; outline: none; }
  #list { list-style: none; margin: 0; padding: 0; max-height: 50vh; overflow: auto; }
  #list li { padding: .6rem 1rem; cursor: pointer; }
  #list li.active { background: #2563eb; color: #fff; }
</style>

<div id="palette"><div class="box">
  <input id="q" placeholder="Type a command…" autocomplete="off">
  <ul id="list"></ul>
</div></div>

<script>
const commands = [
  { name: "New document",     run: () => alert("new doc") },
  { name: "Open settings",    run: () => alert("settings") },
  { name: "Toggle dark mode", run: () => document.body.classList.toggle("dark") },
  { name: "Export as PDF",    run: () => alert("export") },
  { name: "Sign out",         run: () => alert("bye") },
];

// Every query character must appear in order. Earlier and consecutive matches score higher.
function fuzzyScore(query, text) {
  let score = 0, ti = 0, last = -2;
  const t = text.toLowerCase();
  for (const ch of query.toLowerCase()) {
    const found = t.indexOf(ch, ti);
    if (found === -1) return -1;
    score += found === last + 1 ? 3 : 1;
    score -= found * 0.01;
    last = found; ti = found + 1;
  }
  return score;
}

const palette = document.getElementById("palette");
const input = document.getElementById("q");
const list = document.getElementById("list");
let shown = [], active = 0;

function refresh() {
  shown = commands
    .map(c => ({ c, s: fuzzyScore(input.value, c.name) }))
    .filter(x => x.s >= 0)
    .sort((a, b) => b.s - a.s)
    .map(x => x.c);
  active = 0;
  list.replaceChildren(...shown.map((c, i) => {
    const li = document.createElement("li");
    li.textContent = c.name;
    if (i === active) li.classList.add("active");
    li.onmousedown = e => { e.preventDefault(); run(c); };
    return li;
  }));
}

function run(cmd) { close(); cmd.run(); }
function open() { palette.classList.add("open"); input.value = ""; input.focus(); refresh(); }
function close() { palette.classList.remove("open"); }

document.addEventListener("keydown", e => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
    e.preventDefault();
    palette.classList.contains("open") ? close() : open();
  }
});
input.addEventListener("input", refresh);
input.addEventListener("keydown", e => {
  if (e.key === "Escape") close();
  if (e.key === "ArrowDown") { active = Math.min(active + 1, shown.length - 1); highlight(); e.preventDefault(); }
  if (e.key === "ArrowUp")   { active = Math.max(active - 1, 0); highlight(); e.preventDefault(); }
  if (e.key === "Enter" && shown[active]) run(shown[active]);
});
function highlight() {
  [...list.children].forEach((li, i) => li.classList.toggle("active", i === active));
}
palette.addEventListener("mousedown", e => { if (e.target === palette) close(); });
</script>
```

The scoring rewards consecutive matches, so "nd" ranks "New document" above "Export as PDF". The same pattern works for file pickers and search boxes.

Uses `<canvas>` to resize and re-encode a picked image as JPEG or WebP. No server work is needed to shrink the file.

```html
<input type="file" id="pick" accept="image/*">
<p id="info"></p>
<img id="preview" alt="" style="max-width:300px">

<script>
async function compress(file, { maxSide = 1600, quality = 0.8, type = "image/webp" } = {}) {
  const bitmap = await createImageBitmap(file);          // decodes off the main thread
  const scale = Math.min(1, maxSide / Math.max(bitmap.width, bitmap.height));
  const w = Math.round(bitmap.width * scale);
  const h = Math.round(bitmap.height * scale);

  const canvas = new OffscreenCanvas(w, h);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(bitmap, 0, 0, w, h);
  bitmap.close();                                        // free decoded pixels

  const blob = await canvas.convertToBlob({ type, quality });
  return { blob, width: w, height: h };
}

document.getElementById("pick").addEventListener("change", async e => {
  const file = e.target.files[0];
  if (!file) return;
  const { blob, width, height } = await compress(file);
  document.getElementById("preview").src = URL.createObjectURL(blob);
  document.getElementById("info").textContent =
    `${(file.size / 1024).toFixed(0)} KB → ${(blob.size / 1024).toFixed(0)} KB (${width}×${height})`;
  // upload with fetch(url, { method: "POST", body: formData }) where formData.append("image", blob, "photo.webp")
});
</script>
```

`createImageBitmap` decodes without blocking the page. `OffscreenCanvas` can also run inside a Web Worker, so large batches don't freeze the UI. Some older Safari versions don't support WebP encoding, so check `blob.type` and fall back to `image/jpeg`.

Uses timestamps instead of counting `setInterval` ticks, so the timer stays correct when the tab is throttled in the background. The beep is generated with the Web Audio API, so no audio file is needed.

```html
<div style="font-family:system-ui;text-align:center;margin-top:3rem">
  <h1 id="clock" style="font-size:4rem;font-variant-numeric:tabular-nums">25:00</h1>
  <button id="toggle">Start</button>
  <button id="reset">Reset</button>
</div>

<script>
const WORK = 25 * 60 * 1000;
let remaining = WORK;      // ms left when paused
let endsAt = null;         // timestamp when running
let timerId = null;

const clock = document.getElementById("clock");
const toggle = document.getElementById("toggle");

function format(ms) {
  const s = Math.ceil(ms / 1000);
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}

function beep() {
  const ctx = new AudioContext();
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.frequency.value = 880;
  gain.gain.setValueAtTime(0.3, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1);
  osc.connect(gain).connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 1);
}

function tick() {
  const left = endsAt - Date.now();
  if (left <= 0) {
    clearInterval(timerId); timerId = null; endsAt = null; remaining = WORK;
    clock.textContent = "00:00";
    toggle.textContent = "Start";
    beep();
    return;
  }
  clock.textContent = format(left);
}

toggle.onclick = () => {
  if (timerId) {                      // pause
    remaining = endsAt - Date.now();
    clearInterval(timerId); timerId = null; endsAt = null;
    toggle.textContent = "Start";
  } else {                            // start / resume
    endsAt = Date.now() + remaining;
    timerId = setInterval(tick, 250);
    toggle.textContent = "Pause";
    tick();
  }
};

document.getElementById("reset").onclick = () => {
  clearInterval(timerId); timerId = null; endsAt = null;
  remaining = WORK;
  clock.textContent = format(WORK);
  toggle.textContent = "Start";
};
</script>
```

The browser may delay `setInterval` callbacks in background tabs, but `Date.now()` is still correct when the next tick runs. The `AudioContext` is created on a click so browsers allow sound. Create it lazily, and reuse one context in a larger app.

Only the rows visible in the viewport (plus a small buffer) exist in the DOM. Scrolling reuses a fixed spacer to keep the scrollbar accurate.

```html
<div id="viewport" style="height:400px;overflow:auto;border:1px solid #ccc;position:relative">
  <div id="spacer" style="position:relative"></div>
</div>

<script>
const ROW_H = 32;
const TOTAL = 100_000;
const BUFFER = 8;

const viewport = document.getElementById("viewport");
const spacer = document.getElementById("spacer");
spacer.style.height = `${TOTAL * ROW_H}px`;

const pool = [];                              // reused row elements
for (let i = 0; i < Math.ceil(viewport.clientHeight / ROW_H) + BUFFER * 2; i++) {
  const row = document.createElement("div");
  row.style.cssText = `position:absolute;left:0;right:0;height:${ROW_H}px;line-height:${ROW_H}px;padding:0 .5rem;box-sizing:border-box`;
  spacer.append(row);
  pool.push(row);
}

function render() {
  const first = Math.max(0, Math.floor(viewport.scrollTop / ROW_H) - BUFFER);
  pool.forEach((row, k) => {
    const index = first + k;
    if (index >= TOTAL) { row.style.display = "none"; return; }
    row.style.display = "";
    row.style.transform = `translateY(${index * ROW_H}px)`;
    row.textContent = `Row ${index + 1}`;
  });
}

viewport.addEventListener("scroll", () => requestAnimationFrame(render), { passive: true });
render();
</script>
```

The DOM holds about 25 elements regardless of the dataset size. Transforms are used for positioning, so the browser doesn't re-run layout for each row. Variable-height rows need a measurement cache, and the `ROW_H` constant must change to a per-index lookup.

```html
<canvas id="c" width="800" height="500" style="border:1px solid #888;touch-action:none"></canvas>
<div>
  <button id="undo">Undo</button>
  <button id="redo">Redo</button>
  <button id="save">Save PNG</button>
  <input type="color" id="color" value="#222">
</div>

<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
ctx.lineCap = "round";
ctx.lineWidth = 4;

// Each stroke is stored as a list of points, so undo can replay the whole canvas.
const strokes = [];
const undone = [];
let current = null;

function redraw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const s of strokes) {
    ctx.strokeStyle = s.color;
    ctx.beginPath();
    s.points.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
    ctx.stroke();
  }
}

const pos = e => {
  const r = canvas.getBoundingClientRect();
  return { x: (e.clientX - r.left) * canvas.width / r.width,
           y: (e.clientY - r.top) * canvas.height / r.height };
};

canvas.addEventListener("pointerdown", e => {
  canvas.setPointerCapture(e.pointerId);
  current = { color: document.getElementById("color").value, points: [pos(e)] };
  strokes.push(current);
  undone.length = 0;
});
canvas.addEventListener("pointermove", e => {
  if (!current) return;
  current.points.push(pos(e));
  redraw();
});
canvas.addEventListener("pointerup", () => current = null);

document.getElementById("undo").onclick = () => {
  if (strokes.length) { undone.push(strokes.pop()); redraw(); }
};
document.getElementById("redo").onclick = () => {
  if (undone.length) { strokes.push(undone.pop()); redraw(); }
};
document.getElementById("save").onclick = () => {
  const a = document.createElement("a");
  a.download = "drawing.png";
  a.href = canvas.toDataURL("image/png");
  a.click();
};
</script>
```

Pointer events handle mouse, touch, and pen with one code path. `setPointerCapture` keeps the stroke going if the cursor leaves the canvas. Storing vector points instead of pixels is what makes undo cheap.

Three files in the same folder, served over HTTPS or `localhost`.

`index.html`:
```html
<!DOCTYPE html>
<html lang="en">
