  th, td { text-align: left; padding: .4rem; border-bottom: 1px solid #eee; }
  td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
  .income { color: var(--green); }
  .expense { color: var(--red); }
  svg text { font-size: 12px; fill: var(--ink); }
  @media (max-width: 640px) {
    form { grid-template-columns: 1fr 1fr; }
    .summary { flex-direction: column; }
  }
</style>
</head>
<body>
<h1>Budget Tracker</h1>

<form id="entry">
  <label>Date <input type="date" name="date" required></label>
  <label>Description <input name="desc" required maxlength="80"></label>
  <label>Category
    <select name="category">
      <option>Food</option><option>Rent</option><option>Transport</option>
      <option>Fun</option><option>Salary</option><option>Other</option>
    </select>
  </label>
  <label>Amount <input type="number" name="amount" step="0.01" min="0.01" required></label>
  <label>Type
    <select name="type"><option value="expense">Expense</option><option value="income">Income</option></select>
  </label>
  <button>Add</button>
</form>

<section class="summary">
  <div class="card">Income<br><strong id="inc" class="income">0.00</strong></div>
  <div class="card">Expenses<br><strong id="exp" class="expense">0.00</strong></div>
  <div class="card">Balance<br><strong id="bal">0.00</strong></div>
</section>

<svg id="chart" width="100%" height="220" role="img" aria-label="Expenses by category"></svg>
<p><button id="csv">Export CSV</button></p>

<table>
  <thead><tr><th>Date</th><th>Description</th><th>Category</th><th class="num">Amount</th><th></th></tr></thead>
  <tbody id="rows"></tbody>
</table>

<script>
const KEY = "budget-v1";
let items = JSON.parse(localStorage.getItem(KEY) || "[]");   // amounts are integer cents

const $ = id => document.getElementById(id);
const save = () => localStorage.setItem(KEY, JSON.stringify(items));
const fmt = cents => (cents / 100).toFixed(2);
const newId = () => Date.now().toString(36) + Math.random().toString(36).slice(2);

$("entry").addEventListener("submit", e => {
  e.preventDefault();
  const f = Object.fromEntries(new FormData(e.target));
  items.push({
    id: newId(),
    date: f.date,
    desc: f.desc.trim(),
    category: f.category,
    type: f.type,
    amount: Math.round(Number(f.amount) * 100),
  });
  e.target.reset();
  save();
  render();
});

function render() {
  const sum = type => items.filter(i => i.type === type).reduce((s, i) => s + i.amount, 0);
  const income = sum("income"), expense = sum("expense"), balance = income - expense;
  $("inc").textContent = fmt(income);
  $("exp").textContent = fmt(expense);
  $("bal").textContent = fmt(balance);
  $("bal").className = balance < 0 ? "expense" : "income";

  const sorted = [...items].sort((a, b) => b.date.localeCompare(a.date));
  $("rows").replaceChildren(...sorted.map(i => {
    const tr = document.createElement("tr");
    for (const text of [i.date, i.desc, i.category]) {
      const td = document.createElement("td");
      td.textContent = text;                    // user text is never parsed as HTML
      tr.append(td);
    }
    const amount = document.createElement("td");
    amount.className = "num " + (i.type === "income" ? "income" : "expense");
    amount.textContent = (i.type === "income" ? "+" : "-") + fmt(i.amount);
    const del = document.createElement("button");
    del.textContent = "Delete";
    del.onclick = () => { items = items.filter(x => x.id !== i.id); save(); render(); };
    const actions = document.createElement("td");
    actions.append(del);
    tr.append(amount, actions);
    return tr;
  }));
  drawChart();
}

function drawChart() {
  const svg = $("chart");
  const totals = {};
  for (const i of items) if (i.type === "expense") totals[i.category] = (totals[i.category] || 0) + i.amount;
  const data = Object.entries(totals).sort((a, b) => b[1] - a[1]);

  const NS = "http://www.w3.org/2000/svg";
  const W = svg.clientWidth || 800, H = 220, pad = 30;
  const max = Math.max(1, ...data.map(d => d[1]));
  const slot = data.length ? (W - pad * 2) / data.length : 0;
  svg.setAttribute("viewBox", `0 0 ${W} ${H}`);

  svg.replaceChildren(...data.map(([cat, cents], idx) => {
    const h = ((H - 60) * cents) / max;
    const x = pad + idx * slot + slot * 0.15, y = H - 30 - h, w = slot * 0.7;
    const g = document.createElementNS(NS, "g");

    const bar = document.createElementNS(NS, "rect");
    bar.setAttribute("x", x); bar.setAttribute("y", y);
    bar.setAttribute("width", w); bar.setAttribute("height", h);
    bar.setAttribute("fill", "#3b82f6");

    const value = document.createElementNS(NS, "text");
    value.setAttribute("x", x); value.setAttribute("y", y - 6);
    value.textContent = fmt(cents);

    const label = document.createElementNS(NS, "text");
    label.setAttribute("x", x); label.setAttribute("y", H - 10);
    label.textContent = cat;

    g.append(bar, value, label);
    return g;
  }));
}

$("csv").onclick = () => {
  const esc = s => `"${String(s).replace(/"/g, '""')}"`;   // RFC 4180 quoting
  const rows = items.map(i => [i.date, esc(i.desc), i.category, i.type, fmt(i.amount)].join(","));
  const blob = new Blob(["date,description,category,type,amount\n" + rows.join("\n")], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  Object.assign(document.createElement("a"), { href: url, download: "budget.csv" }).click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

render();
</script>
</body>
</html>
```

Save it as budget.html and open it in a browser. Data stays on the device.

Plan: one HTML file. Each card carries SM-2 state (ease factor, repetition count, interval in days). Rating a card Again sends it back within ten minutes, and the other ratings schedule it using the SM-2 formula. Cards persist in localStorage.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Flashcards (SM-2)</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; text-align: center; }
  .card { border: 1px solid #ddd; border-radius: 12px; padding: 2rem 1rem; min-height: 180px; display: flex; flex-direction: column; justify-content: center; }
  #front { font-size: 1.4rem; }
  #back { display: none; margin-top: 1.25rem; font-size: 1.2rem; color: #2563eb; }
  #study.shown #back { display: block; }
  .ratings button { margin: .25rem; padding: .6rem 1rem; }
  textarea { width: 100%; height: 120px; font: inherit; box-sizing: border-box; }
  #stats { color: #6b7280; }
</style>
</head>
<body>
<h1>Flashcards</h1>
<p id="stats"></p>

<section id="study">
  <div class="card">
    <div id="front"></div>
    <div id="back"></div>
  </div>
  <p><button id="reveal">Show answer</button></p>
  <div class="ratings" id="ratings" hidden>
    <button data-q="0">Again</button>
    <button data-q="3">Hard</button>
    <button data-q="4">Good</button>
    <button data-q="5">Easy</button>
  </div>
</section>

<h2>Add cards</h2>
<p>One card per line, written as <code>front | back</code>.</p>
<textarea id="import" placeholder="capital of France | Paris"></textarea>
<p><button id="add">Add cards</button></p>

<script>
const KEY = "flashcards-sm2-v1";
const DAY = 86400000;
const $ = id => document.getElementById(id);
let cards = JSON.parse(localStorage.getItem(KEY) || "[]");
// card: { front, back, ef, reps, interval (days), due (ms timestamp) }
let current = null;

const save = () => localStorage.setItem(KEY, JSON.stringify(cards));
const dueCards = () => cards.filter(c => c.due <= Date.now()).sort((a, b) => a.due - b.due);

// SM-2 (SuperMemo 2). Quality 0-5; below 3 means the card was forgotten.
function review(card, q) {
  card.ef = Math.max(1.3, card.ef + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02)));
  if (q < 3) {
    card.reps = 0;
    card.interval = 1;
  } else {
    card.reps += 1;
    if (card.reps === 1) card.interval = 1;
    else if (card.reps === 2) card.interval = 6;
    else card.interval = Math.round(card.interval * card.ef);
  }
  // Forgotten cards return in ten minutes; the rest wait the scheduled number of days.
  card.due = Date.now() + (q < 3 ? 10 * 60 * 1000 : card.interval * DAY);
  save();
}

function showNext() {
  const due = dueCards();
  current = due[0] ?? null;
  $("stats").textContent = `${due.length} due · ${cards.length} total`;
  $("front").textContent = current ? current.front : (cards.length ? "All caught up." : "No cards yet. Add some below.");
  $("back").textContent = current ? current.back : "";
  $("study").classList.remove("shown");
  $("reveal").hidden = !current;
  $("ratings").hidden = true;
}

$("reveal").onclick = () => {
  $("study").classList.add("shown");
  $("reveal").hidden = true;
  $("ratings").hidden = false;
};

$("ratings").addEventListener("click", e => {
  const btn = e.target.closest("button[data-q]");
  if (!btn || !current) return;
  review(current, Number(btn.dataset.q));
  showNext();
});

$("add").onclick = () => {
  let added = 0;
  for (const line of $("import").value.split("\n")) {
    const [front, ...rest] = line.split("|");
    const back = rest.join("|").trim();
    if (!front.trim() || !back) continue;
    cards.push({ front: front.trim(), back, ef: 2.5, reps: 0, interval: 0, due: Date.now() });
    added++;
  }
  $("import").value = "";
  save();
  showNext();
  alert(`Added ${added} card(s).`);
};

showNext();
</script>
</body>
</html>
```

Save as flashcards.html. A card is due when its `due` time has passed, and the study queue is ordered by due time.

Plan: a 9x9 board with 10 mines. Mines are placed after the first click, excluding that cell and its neighbours, so the first click is always safe. Empty regions open with an iterative flood fill, so large boards cannot overflow the call stack. Right-click flags a cell.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Minesweeper</title>
<style>
  body { font-family: system-ui, sans-serif; text-align: center; user-select: none; }
  #board { display: inline-grid; gap: 2px; background: #888; padding: 2px; margin: 1rem auto; }
  .cell { width: 30px; height: 30px; background: #bdbdbd; display: flex; align-items: center; justify-content: center; font-weight: 700; cursor: pointer; }
  .cell.open { background: #e5e5e5; cursor: default; }
  .cell.boom { background: #f87171; }
  .cell.flag::after { content: "🚩"; }
  .n1 { color: #2563eb; } .n2 { color: #16a34a; } .n3 { color: #dc2626; } .n4 { color: #7c3aed; }
  #status { min-height: 1.5em; font-size: 1.1rem; }
  button { padding: .4rem .9rem; }
</style>
</head>
<body>
<h2>Minesweeper</h2>
<div>Mines left: <span id="left">10</span> &nbsp;·&nbsp; Time: <span id="time">0</span>s</div>
<div id="board"></div>
<div id="status"></div>
<button id="restart">New game</button>
<p>Right-click (or long-press on touch screens) to flag a cell.</p>

<script>
const ROWS = 9, COLS = 9, MINES = 10;
const boardEl = document.getElementById("board");
const $ = id => document.getElementById(id);
let grid, over, started, timer, startedAt;

function reset() {
  clearInterval(timer);
  grid = Array.from({ length: ROWS }, () =>
    Array.from({ length: COLS }, () => ({ mine: false, open: false, flag: false, n: 0 })));
  over = false;
  started = false;
  boardEl.style.gridTemplateColumns = `repeat(${COLS}, 30px)`;
  boardEl.replaceChildren(...Array.from({ length: ROWS * COLS }, (_, i) => {
    const el = document.createElement("div");
    el.className = "cell";
    el.dataset.i = i;
    return el;
  }));
  $("time").textContent = "0";
  $("status").textContent = "";
  draw();
}

function neighbors(r, c) {
  const out = [];
  for (let dr = -1; dr <= 1; dr++)
    for (let dc = -1; dc <= 1; dc++) {
      const rr = r + dr, cc = c + dc;
      if ((dr || dc) && rr >= 0 && rr < ROWS && cc >= 0 && cc < COLS) out.push([rr, cc]);
    }
  return out;
}

// Mines are placed after the first click, so the clicked cell and its neighbours stay clear.
function placeMines(safeR, safeC) {
  const spots = [];
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++)
      if (Math.abs(r - safeR) > 1 || Math.abs(c - safeC) > 1) spots.push([r, c]);
  for (let i = spots.length - 1; i > 0; i--) {          // Fisher-Yates shuffle
    const j = Math.floor(Math.random() * (i + 1));
    [spots[i], spots[j]] = [spots[j], spots[i]];
  }
  for (const [r, c] of spots.slice(0, MINES)) grid[r][c].mine = true;
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++)
      grid[r][c].n = neighbors(r, c).filter(([y, x]) => grid[y][x].mine).length;
}

// Iterative flood fill: opens zero-valued cells and their neighbours.
function reveal(r, c) {
  const stack = [[r, c]];
  while (stack.length) {
    const [y, x] = stack.pop();
    const cell = grid[y][x];
    if (cell.open || cell.flag) continue;
    cell.open = true;
    if (cell.n === 0) for (const p of neighbors(y, x)) stack.push(p);
  }
}

function draw() {
  const flags = grid.flat().filter(c => c.flag).length;
  $("left").textContent = MINES - flags;
  [...boardEl.children].forEach((el, i) => {
    const cell = grid[Math.floor(i / COLS)][i % COLS];
    el.className = "cell";
    el.textContent = "";
    if (cell.open) {
      el.classList.add("open");
      if (cell.mine) { el.classList.add("boom"); el.textContent = "💣"; }
      else if (cell.n) { el.textContent = cell.n; el.classList.add("n" + Math.min(cell.n, 4)); }
    } else if (cell.flag) {
      el.classList.add("flag");
    }
  });
}

function endGame(won) {
  over = true;
  clearInterval(timer);
  if (!won) grid.flat().forEach(c => { if (c.mine) c.open = true; });
  draw();
  $("status").textContent = won ? "You win!" : "Boom! Game over.";
}

boardEl.addEventListener("click", e => {
  const el = e.target.closest(".cell");
  if (!el || over) return;
  const i = Number(el.dataset.i), r = Math.floor(i / COLS), c = i % COLS;
  const cell = grid[r][c];
  if (cell.open || cell.flag) return;

  if (!started) {
    started = true;
    placeMines(r, c);
    startedAt = Date.now();
    timer = setInterval(() => {
      $("time").textContent = Math.floor((Date.now() - startedAt) / 1000);
    }, 250);
  }
  if (cell.mine) { cell.open = true; endGame(false); return; }

  reveal(r, c);
  draw();
  if (grid.flat().every(x => x.mine || x.open)) endGame(true);
});

boardEl.addEventListener("contextmenu", e => {
  e.preventDefault();
  const el = e.target.closest(".cell");
  if (!el || over) return;
  const i = Number(el.dataset.i), cell = grid[Math.floor(i / COLS)][i % COLS];
  if (!cell.open) { cell.flag = !cell.flag; draw(); }
});

$("restart").onclick = reset;
reset();
</script>
</body>
</html>
```

Save as minesweeper.html and open it in a browser.

Plan: a canvas game driven by requestAnimationFrame. The paddle deflects the ball at an angle that depends on the hit position. Bricks use axis-aligned collision, and the ball bounces on the axis with the smaller penetration, which stops it from getting stuck inside a brick. The game has explicit states (ready, playing, over, won).

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Breakout</title>
<style>
  html, body { margin: 0; background: #0f172a; color: #e2e8f0; font-family: system-ui, sans-serif; }
  body { display: flex; flex-direction: column; align-items: center; padding: 8px; }
  canvas { background: #020617; max-width: 100%; height: auto; border-radius: 8px; touch-action: none; }
</style>
</head>
<body>
<div id="hud"></div>
<canvas id="game" width="480" height="560"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const hud = document.getElementById("hud");
const W = canvas.width, H = canvas.height;
const PADDLE = { w: 80, h: 12, y: H - 30, speed: 7 };
const BALL_R = 7;
const COLORS = ["#f43f5e", "#f59e0b", "#84cc16", "#06b6d4", "#8b5cf6"];

let state, paddleX, ball, bricks, score, lives;
const keys = {};

function makeBricks() {
  const rows = 5, cols = 9, bw = 48, bh = 18, gap = 6;
  const left = (W - (cols * (bw + gap) - gap)) / 2;
  const list = [];
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++)
      list.push({ x: left + c * (bw + gap), y: 60 + r * (bh + gap), w: bw, h: bh, alive: true, color: COLORS[r] });
  return list;
}

function resetBall() {
  ball = { x: paddleX + PADDLE.w / 2, y: PADDLE.y - BALL_R - 1, vx: 0, vy: 0 };
}

function updateHud(msg) {
  hud.textContent = `Score ${score} · Lives ${lives} · ${msg}`;
}

function reset() {
  paddleX = (W - PADDLE.w) / 2;
  bricks = makeBricks();
  score = 0;
  lives = 3;
  state = "ready";
  resetBall();
  updateHud("Press Space or click to launch");
}

function launch() {
  const angle = -Math.PI / 2 + (Math.random() - 0.5) * 0.6;   // roughly upward
  const speed = 5;
  ball.vx = Math.cos(angle) * speed;
  ball.vy = Math.sin(angle) * speed;
  state = "playing";
  updateHud("Break them all!");
}

function onAction() {
  if (state === "over" || state === "won") reset();
  else if (state === "ready") launch();
}

function step() {
  if (keys.ArrowLeft) paddleX -= PADDLE.speed;
  if (keys.ArrowRight) paddleX += PADDLE.speed;
  paddleX = Math.max(0, Math.min(W - PADDLE.w, paddleX));

  if (state === "ready") {                  // the ball rides on the paddle until launch
    ball.x = paddleX + PADDLE.w / 2;
    return;
  }
  if (state !== "playing") return;

  ball.x += ball.vx;
  ball.y += ball.vy;

  if (ball.x - BALL_R < 0) { ball.x = BALL_R; ball.vx = Math.abs(ball.vx); }
  if (ball.x + BALL_R > W) { ball.x = W - BALL_R; ball.vx = -Math.abs(ball.vx); }
  if (ball.y - BALL_R < 0) { ball.y = BALL_R; ball.vy = Math.abs(ball.vy); }

  // Paddle: the bounce angle depends on where the ball lands.
  const hitting = ball.vy > 0 &&
    ball.y + BALL_R >= PADDLE.y && ball.y + BALL_R <= PADDLE.y + PADDLE.h + ball.vy &&
    ball.x >= paddleX && ball.x <= paddleX + PADDLE.w;
  if (hitting) {
    const offset = (ball.x - (paddleX + PADDLE.w / 2)) / (PADDLE.w / 2);   // -1 .. 1
    const angle = -Math.PI / 2 + offset * (Math.PI / 3);                    // up to 60 degrees
    const speed = Math.hypot(ball.vx, ball.vy);
    ball.vx = Math.cos(angle) * speed;
    ball.vy = Math.sin(angle) * speed;
    ball.y = PADDLE.y - BALL_R;
  }

  // Bricks: one hit per frame, bouncing on the axis with the smaller overlap.
  for (const b of bricks) {
    if (!b.alive) continue;
    const hit = ball.x + BALL_R > b.x && ball.x - BALL_R < b.x + b.w &&
                ball.y + BALL_R > b.y && ball.y - BALL_R < b.y + b.h;
    if (!hit) continue;
    b.alive = false;
    score += 10;
    const overlapX = Math.min(ball.x + BALL_R - b.x, b.x + b.w - (ball.x - BALL_R));
    const overlapY = Math.min(ball.y + BALL_R - b.y, b.y + b.h - (ball.y - BALL_R));
    if (overlapX < overlapY) ball.vx = -ball.vx; else ball.vy = -ball.vy;
    break;
  }

  if (ball.y - BALL_R > H) {                // the ball fell past the paddle
    lives--;
    if (lives === 0) {
      state = "over";
      updateHud("Game over. Press Space to restart");
    } else {
      state = "ready";
      resetBall();
      updateHud("Press Space to continue");
    }
    return;
  }

  if (bricks.every(b => !b.alive)) {
    state = "won";
    updateHud("You win! Press Space to play again");
  }
}

function draw() {
  ctx.clearRect(0, 0, W, H);
  for (const b of bricks) {
    if (!b.alive) continue;
    ctx.fillStyle = b.color;
    ctx.fillRect(b.x, b.y, b.w, b.h);
  }
  ctx.fillStyle = "#e2e8f0";
  ctx.fillRect(paddleX, PADDLE.y, PADDLE.w, PADDLE.h);
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, BALL_R, 0, Math.PI * 2);
  ctx.fillStyle = "#facc15";
  ctx.fill();
}

function frame() {
  step();
  draw();
  requestAnimationFrame(frame);
}

addEventListener("keydown", e => {
  if (e.key === "ArrowLeft" || e.key === "ArrowRight") keys[e.key] = true;
  if (e.code === "Space") { e.preventDefault(); onAction(); }
});
addEventListener("keyup", e => { keys[e.key] = false; });

canvas.addEventListener("pointermove", e => {
  const rect = canvas.getBoundingClientRect();
  const x = (e.clientX - rect.left) * (W / rect.width);
  paddleX = Math.max(0, Math.min(W - PADDLE.w, x - PADDLE.w / 2));
});
canvas.addEventListener("pointerdown", onAction);

reset();
frame();
</script>
</body>
</html>
```

Save as breakout.html. Arrow keys or the mouse move the paddle, and Space or a click launches the ball.

Plan: a single page that compiles the pattern on every keystroke, highlights matches in the test text, and lists each match with its index and capture groups. Invalid patterns show the engine's error message instead of failing silently. Matches are rendered as text nodes, so the tested text is never parsed as HTML.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Regex Tester</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 860px; margin: 2rem auto; padding: 0 1rem; }
  #pattern { width: 100%; font: 16px ui-monospace, monospace; padding: .5rem; box-sizing: border-box; }
  #text { width: 100%; height: 150px; font: 14px ui-monospace, monospace; padding: .5rem; box-sizing: border-box; }
  #out { white-space: pre-wrap; word-break: break-word; border: 1px solid #ddd; border-radius: 6px; padding: .75rem; min-height: 4rem; font: 14px/1.6 ui-monospace, monospace; }
  mark { background: #fde68a; border-radius: 3px; }
  #error { color: #dc2626; min-height: 1.2em; }
  table { border-collapse: collapse; width: 100%; margin-top: 1rem; font-size: 14px; }
  th, td { border-bottom: 1px solid #eee; padding: .35rem; text-align: left; vertical-align: top; }
  label { margin-right: .9rem; }
</style>
</head>
<body>
<h1>Regex Tester</h1>
<input id="pattern" value="(\w+)@(\w+)\.com" aria-label="Regular expression">
<p>
  <label><input type="checkbox" value="i"> i (ignore case)</label>
  <label><input type="checkbox" value="m"> m (multiline)</label>
  <label><input type="checkbox" value="s"> s (dotAll)</label>
  <label><input type="checkbox" value="u"> u (unicode)</label>
</p>
<textarea id="text">Contact ana@example.com or OMAR@test.com for details.</textarea>
<p id="error" role="alert"></p>
<div id="out"></div>
<table>
  <thead><tr><th>#</th><th>Match</th><th>Index</th><th>Groups</th></tr></thead>
  <tbody id="rows"></tbody>
</table>

<script>
const $ = id => document.getElementById(id);

function run() {
  const text = $("text").value;
  const flags = [...document.querySelectorAll("p input:checked")].map(b => b.value).join("");
  $("error").textContent = "";
  $("out").replaceChildren();
  $("rows").replaceChildren();

  let re;
  try {
    re = new RegExp($("pattern").value, flags + "g");   // matchAll requires the g flag
  } catch (err) {
    $("error").textContent = err.message;
    $("out").textContent = text;
    return;
  }

  let last = 0, n = 0;
  for (const m of text.matchAll(re)) {
    $("out").append(text.slice(last, m.index));         // text nodes, so no HTML injection
    const mark = document.createElement("mark");
    mark.textContent = m[0];
    $("out").append(mark);
    last = m.index + m[0].length;
    n++;

    const groups = m.slice(1).map((g, i) => `$${i + 1}=${g ?? "undefined"}`).join("  ") || "none";
    const tr = document.createElement("tr");
    for (const cell of [n, m[0] || "(empty)", m.index, groups]) {
      const td = document.createElement("td");
      td.textContent = cell;
      tr.append(td);
    }
    $("rows").append(tr);
  }
  $("out").append(text.slice(last));
  if (n === 0) $("rows").innerHTML = '<tr><td colspan="4">No matches</td></tr>';
}

$("pattern").addEventListener("input", run);
$("text").addEventListener("input", run);
document.querySelectorAll("p input[type=checkbox]").forEach(b => b.addEventListener("change", run));
run();
</script>
</body>
</html>
```

