Plan: a recursive renderer built on the native details and summary elements, so collapsing needs no JavaScript. Children are built lazily the first time a node opens, which keeps very large documents responsive. Each node has a copy-path button that produces a JSONPath-style location.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>JSON Explorer</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 1rem; }
  .split { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; height: 80vh; }
  textarea { width: 100%; height: 100%; box-sizing: border-box; font: 13px ui-monospace, monospace; }
  #tree { overflow: auto; font: 13px/1.6 ui-monospace, monospace; }
  details { margin-left: 1.1rem; }
  summary { cursor: pointer; }
  .k { color: #7c3aed; }
  .s { color: #15803d; } .n { color: #2563eb; } .b { color: #d97706; } .z { color: #6b7280; }
  .copy { font-size: 11px; color: #6b7280; margin-left: .6rem; text-decoration: underline; }
  #err { color: #dc2626; white-space: pre-wrap; }
  @media (max-width: 700px) { .split { grid-template-columns: 1fr; height: auto; } }
</style>
</head>
<body>
<div class="split">
  <textarea id="src" spellcheck="false">{"name":"app","version":2,"tags":["a","b"],"owner":{"id":7,"active":true,"note":null}}</textarea>
  <div>
    <div id="err"></div>
    <div id="tree"></div>
  </div>
</div>

<script>
const $ = id => document.getElementById(id);
const VALUE_CLASS = { string: "s", number: "n", boolean: "b" };

function pathSegment(key, isArray) {
  if (isArray) return `[${key}]`;
  return /^[A-Za-z_$][\w$]*$/.test(key) ? `.${key}` : `[${JSON.stringify(key)}]`;
}

// Children are built the first time the node opens, so huge documents stay responsive.
function makeNode(label, value, path) {
  const isContainer = value !== null && typeof value === "object";
  const wrap = document.createElement(isContainer ? "details" : "div");
  const head = document.createElement(isContainer ? "summary" : "span");

  if (label !== null) {
    const k = document.createElement("span");
    k.className = "k";
    k.textContent = label + ": ";
    head.append(k);
  }

  if (isContainer) {
    const isArray = Array.isArray(value);
    const count = isArray ? value.length : Object.keys(value).length;
    head.append(isArray ? `[ ${count} ]` : `{ ${count} }`);
  } else {
    const v = document.createElement("span");
    v.className = VALUE_CLASS[typeof value] ?? "z";
    v.textContent = JSON.stringify(value);
    head.append(v);
  }

  const copy = document.createElement("span");
  copy.className = "copy";
  copy.textContent = "copy path";
  copy.onclick = e => {
    e.preventDefault();                       // stops the click from toggling <details>
    navigator.clipboard?.writeText(path);
    copy.textContent = "copied";
  };
  head.append(copy);
  wrap.append(head);

  if (isContainer) {
    let built = false;
    const build = () => {
      if (built) return;
      built = true;
      const isArray = Array.isArray(value);
      for (const [k, v] of Object.entries(value)) {
        const childLabel = isArray ? `[${k}]` : k;
        wrap.append(makeNode(childLabel, v, path + pathSegment(k, isArray)));
      }
    };
    wrap.addEventListener("toggle", () => { if (wrap.open) build(); });
    if (path === "$") { wrap.open = true; build(); }
  }
  return wrap;
}

function render() {
  $("err").textContent = "";
  try {
    const data = JSON.parse($("src").value);
    $("tree").replaceChildren(makeNode(null, data, "$"));
  } catch (err) {
    $("tree").replaceChildren();
    $("err").textContent = "Invalid JSON: " + err.message;
  }
}

$("src").addEventListener("input", render);
render();
</script>
</body>
</html>
```

