Plan: money is tracked in integer cents. Each expense is split equally across the group, and leftover cents go to the first people in the list so the total always balances exactly. Net balances are then settled with a greedy algorithm that matches the largest debtor with the largest creditor. This needs at most n-1 payments. Finding the true minimum number of payments is NP-hard, so greedy is the practical choice.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Split Expenses</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 680px; margin: 2rem auto; padding: 0 1rem; }
  input, button { font: inherit; padding: .45rem; }
  .row { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: .6rem; }
  table { width: 100%; border-collapse: collapse; margin: .5rem 0 1.5rem; }
  td { border-bottom: 1px solid #eee; padding: .35rem; }
  td.amt { text-align: right; font-variant-numeric: tabular-nums; }
  #msg { color: #dc2626; min-height: 1.2em; }
</style>
</head>
<body>
<h1>Split expenses</h1>

<div class="row">
  <input id="person" placeholder="Person name">
  <button id="addPerson">Add person</button>
</div>

<div class="row">
  <input id="payer" list="people" placeholder="Paid by">
  <input id="amount" type="number" step="0.01" min="0.01" placeholder="Amount">
  <input id="what" placeholder="For what">
  <button id="addExpense">Add expense</button>
  <datalist id="people"></datalist>
</div>
<p id="msg" role="alert"></p>

<h2>Balances</h2>
<table><tbody id="balances"></tbody></table>

<h2>Settle up</h2>
<ul id="settle"></ul>

<script>
const $ = id => document.getElementById(id);
const people = new Set();
const expenses = [];                      // { payer, amount (integer cents), what }

const toCents = x => Math.round(Number(x) * 100);
const money = c => (c / 100).toFixed(2);

$("addPerson").onclick = () => {
  const name = $("person").value.trim();
  if (name) people.add(name);
  $("person").value = "";
  refresh();
};

$("addExpense").onclick = () => {
  const payer = $("payer").value.trim();
  const amount = toCents($("amount").value);
  if (!people.has(payer)) return $("msg").textContent = "The payer must be an existing person.";
  if (!(amount > 0)) return $("msg").textContent = "Enter an amount above zero.";
  expenses.push({ payer, amount, what: $("what").value.trim() });
  $("payer").value = $("amount").value = $("what").value = "";
  $("msg").textContent = "";
  refresh();
};

// Net balance per person: positive means owed money, negative means owes money.
// Each expense is split equally among everyone in the group at calculation time.
function balances() {
  const net = Object.fromEntries([...people].map(p => [p, 0]));
  const n = people.size;
  for (const e of expenses) {
    const share = Math.floor(e.amount / n);
    let extra = e.amount - share * n;     // leftover cents go to the first few people
    for (const p of people) {
      net[p] -= share + (extra > 0 ? 1 : 0);
      if (extra > 0) extra--;
    }
    net[e.payer] += e.amount;
  }
  return net;
}

// Greedy settlement: pair the largest debtor with the largest creditor.
function settle(net) {
  const creditors = [], debtors = [];
  for (const [p, v] of Object.entries(net)) {
    if (v > 0) creditors.push({ p, v });
    if (v < 0) debtors.push({ p, v: -v });
  }
  creditors.sort((a, b) => b.v - a.v);
  debtors.sort((a, b) => b.v - a.v);

  const payments = [];
  let i = 0, j = 0;
  while (i < debtors.length && j < creditors.length) {
    const pay = Math.min(debtors[i].v, creditors[j].v);
    payments.push({ from: debtors[i].p, to: creditors[j].p, amount: pay });
    debtors[i].v -= pay;
    creditors[j].v -= pay;
    if (debtors[i].v === 0) i++;
    if (creditors[j].v === 0) j++;
  }
  return payments;
}

function refresh() {
  $("people").replaceChildren(...[...people].map(p => {
    const o = document.createElement("option");
    o.value = p;
    return o;
  }));

  const net = balances();
  $("balances").replaceChildren(...Object.entries(net).map(([p, c]) => {
    const tr = document.createElement("tr");
    const name = document.createElement("td");
    name.textContent = p;
    const amt = document.createElement("td");
    amt.className = "amt";
    amt.textContent = (c >= 0 ? "+" : "-") + money(Math.abs(c));
    tr.append(name, amt);
    return tr;
  }));

  $("settle").replaceChildren(...settle(net).map(t => {
    const li = document.createElement("li");
    li.textContent = `${t.from} pays ${t.to} ${money(t.amount)}`;
    return li;
  }));
}

refresh();
</script>
</body>
</html>
```

