Plan: days are stored as UTC date keys ("YYYY-MM-DD") so timezone changes cannot shift entries. The heatmap covers 53 weeks and aligns columns to Sundays. Current and best streaks are computed from the stored dates. Future days are locked.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Habit Tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 2rem; color: #111827; }
  .controls { display: flex; gap: .5rem; flex-wrap: wrap; align-items: center; margin-bottom: 1rem; }
  input, select, button { font: inherit; padding: .4rem .6rem; }
  .grid { display: grid; grid-auto-flow: column; grid-template-rows: repeat(7, 14px); gap: 3px; overflow-x: auto; padding-bottom: .5rem; }
  .day { width: 14px; height: 14px; border-radius: 3px; background: #ebedf0; cursor: pointer; }
  .day.done { background: #216e39; }
  .day.today { outline: 2px solid #2563eb; outline-offset: 1px; }
  .stats { color: #374151; }
</style>
</head>
<body>
<h1 id="title">Habit Tracker</h1>
<div class="controls">
  <input id="newName" placeholder="New habit, e.g. Read 20 min">
  <button id="create">Create</button>
  <select id="pick" aria-label="Choose habit"></select>
</div>
<p class="stats">Current streak: <strong id="current">0</strong> days · Best streak: <strong id="best">0</strong> days</p>
<div class="grid" id="grid" aria-label="Last 53 weeks"></div>
<p><small>Click a day to toggle it. Days are stored by UTC date.</small></p>

<script>
const KEY = "habits-v1";
const DAY_MS = 86400000;
const $ = id => document.getElementById(id);
let store = JSON.parse(localStorage.getItem(KEY) || '{"habits":{}}');
let current = Object.keys(store.habits)[0] ?? null;

const save = () => localStorage.setItem(KEY, JSON.stringify(store));
const dayKey = ms => new Date(ms).toISOString().slice(0, 10);          // "YYYY-MM-DD" in UTC
const todayMs = () => Date.parse(dayKey(Date.now()) + "T00:00:00Z");
const todayKey = () => dayKey(todayMs());

// done is an object such as { "2026-10-11": true }
function streaks(done) {
  const days = Object.keys(done).sort();              // ISO dates sort chronologically
  let best = 0, run = 0, prev = null;
  for (const d of days) {
    const t = Date.parse(d + "T00:00:00Z");
    run = prev !== null && t - prev === DAY_MS ? run + 1 : 1;
    best = Math.max(best, run);
    prev = t;
  }
  // The current streak counts back from today. If today is not done yet, it counts from yesterday.
  let cursor = todayMs();
  if (!done[dayKey(cursor)]) cursor -= DAY_MS;
  let now = 0;
  while (done[dayKey(cursor)]) { now++; cursor -= DAY_MS; }
  return { current: now, best };
}

function renderGrid(done) {
  const end = todayMs();
  let start = end - 370 * DAY_MS;
  start -= new Date(start).getUTCDay() * DAY_MS;      // align columns to Sundays
  const today = todayKey();
  const cells = [];
  for (let t = start; t <= end; t += DAY_MS) {
    const key = dayKey(t);
    const cell = document.createElement("div");
    cell.className = "day" + (done[key] ? " done" : "") + (key === today ? " today" : "");
    cell.dataset.key = key;
    cell.title = key;
    cells.push(cell);
  }
  $("grid").replaceChildren(...cells);
}

function render() {
  $("pick").replaceChildren(...Object.keys(store.habits).map(name => {
    const o = document.createElement("option");
    o.value = name;
    o.textContent = name;
    o.selected = name === current;
    return o;
  }));
  if (!current) {
    $("title").textContent = "Create a habit to begin";
    $("grid").replaceChildren();
    return;
  }
  const done = store.habits[current].done;
  $("title").textContent = current;
  const s = streaks(done);
  $("current").textContent = s.current;
  $("best").textContent = s.best;
  renderGrid(done);
}

$("create").onclick = () => {
  const name = $("newName").value.trim();
  if (!name || store.habits[name]) return;
  store.habits[name] = { done: {} };
  current = name;
  $("newName").value = "";
  save();
  render();
};

$("pick").onchange = e => { current = e.target.value; render(); };

$("grid").addEventListener("click", e => {
  const cell = e.target.closest(".day");
  if (!cell || !current) return;
  const key = cell.dataset.key;
  if (key > todayKey()) return;                       // future days are locked
  const done = store.habits[current].done;
  if (done[key]) delete done[key]; else done[key] = true;
  save();
  render();
});

render();
</script>
</body>
</html>
```

