**TaskRepository.java**
```java
package com.example.tasks;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface TaskRepository extends JpaRepository<Task, Long> {
    List<Task> findByDoneOrderByCreatedAtDesc(boolean done);
}
```

**TaskController.java**
```java
package com.example.tasks;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/tasks")
public class TaskController {
    private final TaskRepository repo;

    public TaskController(TaskRepository repo) { this.repo = repo; }

    @GetMapping
    public List<Task> list(@RequestParam(required = false) Boolean done) {
        return done == null ? repo.findAll() : repo.findByDoneOrderByCreatedAtDesc(done);
    }

    @GetMapping("/{id}")
    public Task get(@PathVariable Long id) {
        return find(id);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public Task create(@Valid @RequestBody TaskRequest req) {
        Task t = new Task(req.title());
        t.setDone(req.done());
        return repo.save(t);
    }

    @PutMapping("/{id}")
    public Task update(@PathVariable Long id, @Valid @RequestBody TaskRequest req) {
        Task t = find(id);
        t.setTitle(req.title());
        t.setDone(req.done());
        return repo.save(t);
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void delete(@PathVariable Long id) {
        repo.delete(find(id));
    }

    private Task find(Long id) {
        return repo.findById(id)
                   .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "task " + id + " not found"));
    }
}
```

