Plan: the server accepts connections and gives each client a virtual thread. A ConcurrentHashMap maps usernames to writers, and putIfAbsent claims a name atomically, so two clients cannot register the same name. Broadcasts and whispers are routed through the map. Cleanup runs in a finally block, so a dropped connection always removes the user and announces the departure. The client uses one thread for incoming messages and the main thread for keyboard input.

**ChatServer.java**
```java
import java.io.*;
import java.net.*;
import java.util.Map;
import java.util.concurrent.*;

public class ChatServer {
    private static final Map<String, PrintWriter> clients = new ConcurrentHashMap<>();
    private static final ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor();

    public static void main(String[] args) throws IOException {
        int port = args.length > 0 ? Integer.parseInt(args[0]) : 5000;
        try (ServerSocket server = new ServerSocket(port)) {
            System.out.println("Chat server listening on port " + port);
            while (true) {
                Socket socket = server.accept();
                pool.submit(() -> handle(socket));
            }
        }
    }

    static void handle(Socket socket) {
        String name = null;
        try (socket;
             BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true)) {

            out.println("Enter a username:");
            String requested = in.readLine();
            if (requested == null || requested.isBlank()) return;
            String candidate = requested.strip();
            if (clients.putIfAbsent(candidate, out) != null) {   // atomic name claim
                out.println("That name is taken.");
                return;
            }
            name = candidate;
            broadcast("* " + name + " joined *", null);

            String line;
            while ((line = in.readLine()) != null) {
                if (line.isBlank()) continue;
                if (line.equals("/quit")) break;
                if (line.equals("/who")) out.println("Online: " + String.join(", ", clients.keySet()));
                else if (line.startsWith("/w ")) whisper(name, line.substring(3), out);
                else broadcast(name + ": " + line, name);
            }
        } catch (IOException ignored) {
            // the connection dropped; cleanup happens in finally
        } finally {
            if (name != null) {
                clients.remove(name);
                broadcast("* " + name + " left *", null);
            }
        }
    }

    static void broadcast(String msg, String exclude) {
        clients.forEach((user, writer) -> {
            if (!user.equals(exclude)) writer.println(msg);
        });
    }

    static void whisper(String from, String rest, PrintWriter sender) {
        int space = rest.indexOf(' ');
        if (space < 0) { sender.println("usage: /w <name> <message>"); return; }
        String to = rest.substring(0, space), text = rest.substring(space + 1);
        PrintWriter target = clients.get(to);
        if (target == null) {
            sender.println("No user named " + to);
        } else {
            target.println("[whisper from " + from + "] " + text);
            sender.println("[whisper to " + to + "] " + text);
        }
    }
}
