Plan: a bounded crawler. Virtual threads fetch pages, a Semaphore caps simultaneous requests, and an AtomicInteger enforces the page budget. A Phaser counts in-flight work, so the main thread knows exactly when the crawl has finished, with no polling. Only same-host http and https links are followed. Fragments are dropped during normalisation so that one page is never crawled twice.

```java
import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Phaser;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Crawler {
    private static final Pattern HREF = Pattern.compile("href\\s*=\\s*\"([^\"#]+)\"", Pattern.CASE_INSENSITIVE);
    private static final Pattern TITLE = Pattern.compile("<title[^>]*>(.*?)</title>",
            Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

    private final HttpClient http = HttpClient.newBuilder()
            .followRedirects(HttpClient.Redirect.NORMAL)
            .connectTimeout(Duration.ofSeconds(5))
            .build();
    private final String host;
    private final Set<URI> seen = ConcurrentHashMap.newKeySet();
    private final Map<URI, String> titles = new ConcurrentHashMap<>();
    private final AtomicInteger budget;
    private final Semaphore concurrency;
    private final Phaser inFlight = new Phaser(1);          // the main thread is the first party
    private final ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor();

    public Crawler(URI start, int maxPages, int maxConcurrentRequests) {
        this.host = start.getHost();
        this.budget = new AtomicInteger(maxPages);
        this.concurrency = new Semaphore(maxConcurrentRequests);
    }

    public Map<URI, String> run(URI start) {
        submit(normalize(start));
        inFlight.arriveAndAwaitAdvance();                    // wait until every page is finished
        pool.close();
        return new TreeMap<>(titles);
    }

    private void submit(URI url) {
        if (!seen.add(url)) return;                          // already queued or visited
        if (budget.getAndDecrement() <= 0) return;           // page limit reached
        inFlight.register();
        pool.execute(() -> {
            try {
                process(url);
            } finally {
                inFlight.arriveAndDeregister();
            }
        });
    }

    private void process(URI url) {
        try {
            concurrency.acquire();
            HttpResponse<String> res;
            try {
                res = http.send(HttpRequest.newBuilder(url).timeout(Duration.ofSeconds(10)).build(),
                                HttpResponse.BodyHandlers.ofString());
            } finally {
                concurrency.release();
            }
            String type = res.headers().firstValue("Content-Type").orElse("");
            if (res.statusCode() != 200 || !type.contains("text/html")) return;

            Matcher title = TITLE.matcher(res.body());
            titles.put(url, title.find() ? title.group(1).strip() : "(no title)");

            Matcher links = HREF.matcher(res.body());
            while (links.find()) {
                URI link = url.resolve(links.group(1));     // handles relative paths
                String scheme = link.getScheme();
                if (("http".equals(scheme) || "https".equals(scheme)) && host.equals(link.getHost())) {
                    submit(normalize(link));
                }
            }
        } catch (IOException | IllegalArgumentException e) {
            // unreachable page or malformed link: skip it
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static URI normalize(URI u) {
        try {
            String path = u.getPath() == null || u.getPath().isEmpty() ? "/" : u.getPath();
            return new URI(u.getScheme(), u.getHost(), path, u.getQuery(), null);   // drops the fragment
        } catch (URISyntaxException e) {
            return u;
        }
    }

    public static void main(String[] args) {
        URI start = URI.create(args.length > 0 ? args[0] : "https://example.com");
        Crawler crawler = new Crawler(start, 50, 8);
        crawler.run(start).forEach((url, title) -> System.out.println(url + "  " + title));
    }
}
```

Run with `javac Crawler.java && java Crawler https://example.com`. Check robots.txt and the site's terms before crawling, and add a delay per host for polite crawling. The regex link extractor is fine for a demo, but use an HTML parser such as jsoup for real pages.

Plan: a console game against a minimax opponent. Minimax searches the whole game tree, and alpha-beta pruning skips branches that cannot change the result. Scores favour faster wins and slower losses, so the AI wins quickly when it can and prolongs a loss when it cannot. Because the search is exhaustive, the AI can never lose.

```java
import java.util.Arrays;
import java.util.Scanner;

public class TicTacToe {
    private static final int[][] LINES = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8},
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8},
        {0, 4, 8}, {2, 4, 6}
    };

    static char winner(char[] b) {
        for (int[] l : LINES)
            if (b[l[0]] != ' ' && b[l[0]] == b[l[1]] && b[l[1]] == b[l[2]]) return b[l[0]];
        return ' ';
    }

    static boolean full(char[] b) {
        for (char c : b) if (c == ' ') return false;
        return true;
    }

    // X maximizes and O minimizes. Scores favour quicker wins and slower losses.
    static int minimax(char[] b, boolean xTurn, int depth, int alpha, int beta) {
        char w = winner(b);
        if (w == 'X') return 10 - depth;
        if (w == 'O') return depth - 10;
        if (full(b)) return 0;

        int best = xTurn ? Integer.MIN_VALUE : Integer.MAX_VALUE;
        for (int i = 0; i < 9; i++) {
            if (b[i] != ' ') continue;
            b[i] = xTurn ? 'X' : 'O';
            int score = minimax(b, !xTurn, depth + 1, alpha, beta);
            b[i] = ' ';
            if (xTurn) {
                best = Math.max(best, score);
                alpha = Math.max(alpha, best);
            } else {
                best = Math.min(best, score);
                beta = Math.min(beta, best);
            }
            if (beta <= alpha) break;               // alpha-beta cutoff
        }
        return best;
    }

    static int bestMoveForO(char[] b) {
        int bestMove = -1, bestScore = Integer.MAX_VALUE;
        for (int i = 0; i < 9; i++) {
            if (b[i] != ' ') continue;
            b[i] = 'O';
            int score = minimax(b, true, 1, Integer.MIN_VALUE, Integer.MAX_VALUE);
            b[i] = ' ';
            if (score < bestScore) { bestScore = score; bestMove = i; }
        }
        return bestMove;
    }

    static void print(char[] b) {
        for (int r = 0; r < 3; r++) {
            System.out.println(" " + b[r * 3] + " | " + b[r * 3 + 1] + " | " + b[r * 3 + 2]);
            if (r < 2) System.out.println("---+---+---");
        }
    }

    static int readMove(Scanner in, char[] b) {
        while (true) {
            System.out.print("Your move (1-9): ");
            if (!in.hasNext()) System.exit(0);                  // end of input
            if (!in.hasNextInt()) { in.next(); System.out.println("Enter a number."); continue; }
            int m = in.nextInt() - 1;
            if (m >= 0 && m < 9 && b[m] == ' ') return m;
            System.out.println("That square is not available.");
        }
    }

    public static void main(String[] args) {
        char[] board = new char[9];
        Arrays.fill(board, ' ');
        Scanner in = new Scanner(System.in);
        boolean humanTurn = true;
        System.out.println("You are X and move first. Squares are numbered 1-9.");

        while (winner(board) == ' ' && !full(board)) {
            print(board);
            if (humanTurn) {
                board[readMove(in, board)] = 'X';
            } else {
                int move = bestMoveForO(board);
                board[move] = 'O';
                System.out.println("AI plays " + (move + 1));
            }
            humanTurn = !humanTurn;
        }
        print(board);
        char w = winner(board);
        System.out.println(w == 'X' ? "You win!" : w == 'O' ? "The AI wins." : "Draw.");
    }
}
```

Compile with `javac TicTacToe.java` and run with `java TicTacToe`. The same minimax pattern extends to any two-player game, provided you can enumerate moves and score terminal positions.

Plan: a backtracking solver with two refinements. Cells are chosen by the Minimum Remaining Values heuristic (fewest candidates first), and candidate digits are kept as bitmasks, so each legality check is a handful of bit operations. The generator fills a random valid grid, then removes clues only while the puzzle still has exactly one solution.

```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class Sudoku {
    private final int[][] g = new int[9][9];

    public Sudoku(int[][] grid) {
        for (int r = 0; r < 9; r++) g[r] = grid[r].clone();
    }

    public int[][] snapshot() {
        int[][] copy = new int[9][9];
        for (int r = 0; r < 9; r++) copy[r] = g[r].clone();
        return copy;
    }

    private static int bit(int digit) { return digit == 0 ? 0 : 1 << digit; }

    // Bit d (1..9) is set when digit d is still legal at (r, c).
    private int candidates(int r, int c) {
        int used = 0;
        for (int i = 0; i < 9; i++) used |= bit(g[r][i]) | bit(g[i][c]);
        int br = (r / 3) * 3, bc = (c / 3) * 3;
        for (int i = br; i < br + 3; i++)
            for (int j = bc; j < bc + 3; j++)
                used |= bit(g[i][j]);
        return ~used & 0b11_1111_1110;                  // keep bits 1..9
    }

    // Minimum Remaining Values: the empty cell with the fewest candidates.
    // Returns {row, col, mask}, or null when the grid is full.
    private int[] mostConstrained() {
        int[] best = null;
        int bestCount = 10;
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++) {
                if (g[r][c] != 0) continue;
                int mask = candidates(r, c);
                int n = Integer.bitCount(mask);
                if (n < bestCount) {
                    bestCount = n;
                    best = new int[] {r, c, mask};
                    if (n == 0) return best;            // dead end: fail fast
                }
            }
        return best;
    }

    /** Solves in place. Returns true and leaves the solution in the grid on success. */
    public boolean solve() {
        int[] cell = mostConstrained();
        if (cell == null) return true;
        for (int d = 1; d <= 9; d++) {
            if ((cell[2] & (1 << d)) == 0) continue;
            g[cell[0]][cell[1]] = d;
            if (solve()) return true;
        }
        g[cell[0]][cell[1]] = 0;
        return false;
    }

    /** Counts solutions up to 'limit' and restores the grid afterwards. */
    public int countSolutions(int limit) {
        int[] cell = mostConstrained();
        if (cell == null) return 1;
        int count = 0;
        for (int d = 1; d <= 9 && count < limit; d++) {
            if ((cell[2] & (1 << d)) == 0) continue;
            g[cell[0]][cell[1]] = d;
            count += countSolutions(limit - count);
            g[cell[0]][cell[1]] = 0;
        }
        return count;
    }

    /** Fills an empty grid with a random valid solution. */
    boolean fillRandomly(Random rnd) {
        int[] cell = mostConstrained();
        if (cell == null) return true;
        if (cell[2] == 0) return false;
        List<Integer> digits = new ArrayList<>();
        for (int d = 1; d <= 9; d++) if ((cell[2] & (1 << d)) != 0) digits.add(d);
        Collections.shuffle(digits, rnd);
        for (int d : digits) {
            g[cell[0]][cell[1]] = d;
            if (fillRandomly(rnd)) return true;
        }
        g[cell[0]][cell[1]] = 0;
        return false;
    }

    /** Removes up to 'holes' clues, keeping only removals that leave exactly one solution. */
    public static int[][] makePuzzle(int[][] solution, int holes, Random rnd) {
        int[][] p = new int[9][9];
        for (int r = 0; r < 9; r++) p[r] = solution[r].clone();
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < 81; i++) order.add(i);
        Collections.shuffle(order, rnd);
        int removed = 0;
        for (int idx : order) {
            if (removed == holes) break;
            int r = idx / 9, c = idx % 9, keep = p[r][c];
            p[r][c] = 0;
            if (new Sudoku(p).countSolutions(2) == 1) removed++;
            else p[r][c] = keep;
        }
        return p;
    }

    static void print(int[][] grid) {
        for (int r = 0; r < 9; r++) {
            if (r > 0 && r % 3 == 0) System.out.println("------+-------+------");
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < 9; c++) {
                if (c > 0 && c % 3 == 0) sb.append("| ");
                sb.append(grid[r][c] == 0 ? ". " : grid[r][c] + " ");
            }
            System.out.println(sb.toString().stripTrailing());
        }
    }

    public static void main(String[] args) {
        Random rnd = new Random();
        Sudoku blank = new Sudoku(new int[9][9]);
        blank.fillRandomly(rnd);
        int[][] puzzle = makePuzzle(blank.snapshot(), 45, rnd);

        System.out.println("Puzzle:");
        print(puzzle);
        Sudoku solver = new Sudoku(puzzle);
        solver.solve();
        System.out.println("\nSolution:");
        print(solver.snapshot());
    }
}
```

Compile with `javac Sudoku.java` and run with `java Sudoku`. A puzzle with exactly one solution is what makes the generator trustworthy, which is why it counts solutions up to two before removing each clue.

Plan: a token-bucket rate limiter with lazy refill, so no background timer is needed. Each client IP gets a bucket that holds a burst of tokens and refills at a steady rate. A request spends one token. Over-limit requests receive 429 with a Retry-After header. Each bucket synchronises on itself, so contention is limited to requests from the same client.

```java
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RateLimitedServer {

    /** Token bucket with lazy refill: tokens are computed from elapsed time on each request. */
    static final class Bucket {
        private final double capacity;
        private final double refillPerNano;
        private double tokens;
        private long lastNanos = System.nanoTime();

        Bucket(double capacity, double tokensPerSecond) {
            this.capacity = capacity;
            this.refillPerNano = tokensPerSecond / 1_000_000_000.0;
            this.tokens = capacity;
        }

        synchronized boolean tryConsume() {
            long now = System.nanoTime();
            tokens = Math.min(capacity, tokens + (now - lastNanos) * refillPerNano);
            lastNanos = now;
            if (tokens < 1) return false;
            tokens -= 1;
            return true;
        }
    }

    private static final int BURST = 10;
    private static final double PER_SECOND = 2;
    private static final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

    static boolean allow(String clientKey) {
        return buckets.computeIfAbsent(clientKey, k -> new Bucket(BURST, PER_SECOND)).tryConsume();
    }

    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/", RateLimitedServer::handle);
        server.start();
        System.out.println("http://localhost:8080  (burst " + BURST + ", " + PER_SECOND + " requests/s per client)");
    }

    static void handle(HttpExchange exchange) throws IOException {
        try {
            String client = exchange.getRemoteAddress().getAddress().getHostAddress();
            if (allow(client)) {
                reply(exchange, 200, "ok\n");
            } else {
                exchange.getResponseHeaders().add("Retry-After", "1");
                reply(exchange, 429, "slow down\n");
            }
        } finally {
            exchange.close();
        }
    }

    static void reply(HttpExchange exchange, int status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(status, bytes.length);
        try (OutputStream os = exchange.getResponseBody()) {
            os.write(bytes);
        }
    }
}
```

Test by sending a quick burst, for example `for i in $(seq 15); do curl -s -o /dev/null -w "%{http_code}\n" localhost:8080; done`. The first 10 succeed, and the rest return 429 until tokens refill. Behind a reverse proxy, key on the trusted `X-Forwarded-For` value rather than the socket address. Also evict idle buckets so memory does not grow without bound.

Plan: an append-only write-ahead log. Each record carries a length and a CRC32 checksum. Writes are fsynced before put returns, so an acknowledged write survives a crash. On startup the log is replayed, and a torn or corrupt tail record is truncated away. Compaction writes only the live keys to a temporary file, fsyncs it, and atomically renames it over the log.

```java
import java.io.Closeable;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.zip.CRC32;

public class KVStore implements Closeable {
    private static final byte PUT = 'P', DELETE = 'D';

    private final Path logPath;
    private final Map<String, String> data = new HashMap<>();
    private FileChannel log;

    public KVStore(Path logPath) throws IOException {
        this.logPath = logPath;
        replay();
        log = FileChannel.open(logPath, StandardOpenOption.CREATE, StandardOpenOption.WRITE,
                StandardOpenOption.APPEND);
    }

    public synchronized Optional<String> get(String key) {
        return Optional.ofNullable(data.get(key));
    }

    public synchronized void put(String key, String value) throws IOException {
        writeRecord(log, PUT, key, value);
        log.force(false);                       // fsync: durable before we return
        data.put(key, value);
    }

    public synchronized void delete(String key) throws IOException {
        writeRecord(log, DELETE, key, "");
        log.force(false);
        data.remove(key);
    }

    /** Rewrites the log with only live keys, then atomically swaps it in. */
    public synchronized void compact() throws IOException {
        Path tmp = logPath.resolveSibling(logPath.getFileName() + ".tmp");
        try (FileChannel out = FileChannel.open(tmp, StandardOpenOption.CREATE,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
            for (Map.Entry<String, String> e : data.entrySet())
                writeRecord(out, PUT, e.getKey(), e.getValue());
            out.force(true);
        }
        log.close();
        Files.move(tmp, logPath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        log = FileChannel.open(logPath, StandardOpenOption.WRITE, StandardOpenOption.APPEND);
    }

    @Override
    public synchronized void close() throws IOException {
        log.close();
    }

    // Record layout: [payloadLength:int][crc32:int][op:byte][keyLen:int][key][valueLen:int][value]
    private static void writeRecord(FileChannel ch, byte op, String key, String value) throws IOException {
        byte[] k = key.getBytes(StandardCharsets.UTF_8);
        byte[] v = value.getBytes(StandardCharsets.UTF_8);
        ByteBuffer payload = ByteBuffer.allocate(1 + 4 + k.length + 4 + v.length)
                .put(op).putInt(k.length).put(k).putInt(v.length).put(v).flip();
        CRC32 crc = new CRC32();
        crc.update(payload.duplicate());
        ByteBuffer header = ByteBuffer.allocate(8)
                .putInt(payload.remaining()).putInt((int) crc.getValue()).flip();
        writeFully(ch, header);
        writeFully(ch, payload);
    }

    private static void writeFully(FileChannel ch, ByteBuffer buf) throws IOException {
        while (buf.hasRemaining()) ch.write(buf);
    }

    private static int readFully(FileChannel ch, ByteBuffer buf) throws IOException {
        int total = 0;
        while (buf.hasRemaining()) {
            int n = ch.read(buf);
            if (n < 0) break;
            total += n;
        }
        return total;
    }

    // Rebuilds state from the log. A torn or corrupt tail record is discarded.
    private void replay() throws IOException {
        if (!Files.exists(logPath)) return;
        long goodBytes = 0;
        try (FileChannel ch = FileChannel.open(logPath, StandardOpenOption.READ)) {
            ByteBuffer header = ByteBuffer.allocate(8);
            while (true) {
                header.clear();
                if (readFully(ch, header) < 8) break;
                header.flip();
                int length = header.getInt(), crc = header.getInt();
                if (length < 9 || length > 64 * 1024 * 1024) break;
                ByteBuffer payload = ByteBuffer.allocate(length);
                if (readFully(ch, payload) < length) break;
                payload.flip();
                CRC32 check = new CRC32();
                check.update(payload.duplicate());
                if ((int) check.getValue() != crc) break;
                apply(payload);
                goodBytes += 8 + length;
            }
        }
        try (FileChannel ch = FileChannel.open(logPath, StandardOpenOption.WRITE)) {
            ch.truncate(goodBytes);               // drop the damaged tail so new records start cleanly
        }
    }

    private void apply(ByteBuffer p) {
        byte op = p.get();
        String key = readString(p);
        String value = readString(p);
        if (op == PUT) data.put(key, value);
        else data.remove(key);
    }

    private static String readString(ByteBuffer p) {
        byte[] bytes = new byte[p.getInt()];
        p.get(bytes);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        try (KVStore db = new KVStore(Path.of("kv.log"))) {
            db.put("user:1", "Ana");
            db.put("user:2", "Omar");
            db.delete("user:2");
            System.out.println(db.get("user:1").orElse("missing"));   // Ana
            db.compact();
        }
    }
}
```

Run with `javac KVStore.java && java KVStore`. Kill the process during a long write loop and run it again: every acknowledged key is still there. This is the same idea behind the logs in LevelDB, Kafka, and most databases.

Plan: a Flask app with three routes. POST /api/links stores a URL and returns a short code. GET /<code> redirects and counts the click. GET /api/links/<code> returns the stats. Codes are base62 encodings of the row id, which keeps them short and needs no collision handling. SQLite is opened per request and closed in teardown, and inputs are validated before they reach the database.

```python
# app.py   (install with: pip install flask)
import sqlite3
import string
from urllib.parse import urlparse

from flask import Flask, abort, g, jsonify, redirect, request

DB_PATH = "shortener.db"
ALPHABET = string.digits + string.ascii_letters          # base62 digits
app = Flask(__name__)


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    with sqlite3.connect(DB_PATH) as con:
        con.execute(
            "CREATE TABLE IF NOT EXISTS links ("
            " id INTEGER PRIMARY KEY AUTOINCREMENT,"
            " url TEXT NOT NULL,"
            " clicks INTEGER NOT NULL DEFAULT 0,"
            " created_at TEXT DEFAULT CURRENT_TIMESTAMP)"
        )


def encode(n: int) -> str:
    if n == 0:
        return ALPHABET[0]
    digits = []
    while n:
        n, r = divmod(n, 62)
        digits.append(ALPHABET[r])
    return "".join(reversed(digits))


def decode(code: str) -> int:
    n = 0
    for ch in code:
        idx = ALPHABET.find(ch)
        if idx < 0:
            raise ValueError(code)
        n = n * 62 + idx
    return n


def valid_url(url: str) -> bool:
    p = urlparse(url)
    return p.scheme in ("http", "https") and bool(p.netloc)


@app.post("/api/links")
def create_link():
    url = str((request.get_json(silent=True) or {}).get("url", "")).strip()
    if not valid_url(url):
        return jsonify(error="url must be an absolute http or https URL"), 400
    db = get_db()
    cur = db.execute("INSERT INTO links (url) VALUES (?)", (url,))
    db.commit()
    code = encode(cur.lastrowid)
    return jsonify(code=code, short_url=request.host_url + code), 201


@app.get("/api/links/<code>")
def link_stats(code):
    try:
        row_id = decode(code)
    except ValueError:
        abort(404)
    row = get_db().execute(
        "SELECT url, clicks, created_at FROM links WHERE id = ?", (row_id,)
    ).fetchone()
    if row is None:
        abort(404)
    return jsonify(url=row["url"], clicks=row["clicks"], created_at=row["created_at"])


@app.get("/<code>")
def follow(code):
    try:
        row_id = decode(code)
    except ValueError:
        abort(404)
    db = get_db()
    row = db.execute("SELECT url FROM links WHERE id = ?", (row_id,)).fetchone()
    if row is None:
        abort(404)
    db.execute("UPDATE links SET clicks = clicks + 1 WHERE id = ?", (row_id,))
    db.commit()
    return redirect(row["url"], code=302)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)
```

Test it with `curl -X POST localhost:5000/api/links -H "Content-Type: application/json" -d '{"url":"https://example.com"}'`. Sequential codes are guessable, so for a public service use random codes with a uniqueness check, or add a salt to the encoding.

Plan: a three-stage pipeline. Stage one groups files by size, which costs only a stat call. Stage two hashes only files that share a size, using SHA-256 in 1 MiB chunks so large files never load into memory. Stage three removes hard links to the same inode, because deleting one of them frees no space. Symlinks are skipped, and --delete is opt-in.

```python
#!/usr/bin/env python3
'''Find duplicate files: group by size first (cheap), then hash only the candidates.'''
import argparse
import hashlib
import os
import stat
from collections import defaultdict
from pathlib import Path


def iter_files(root: Path, min_size: int):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]   # skip hidden directories
        for name in filenames:
            path = Path(dirpath, name)
            try:
                st = path.lstat()                    # lstat: symlinks are not followed
            except OSError:
                continue
            if stat.S_ISREG(st.st_mode) and st.st_size >= min_size:
                yield path, st


def sha256(path: Path, chunk: int = 1 << 20) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(chunk), b""):
            h.update(block)
    return h.hexdigest()


def distinct_inodes(paths):
    # Hard links share one inode and one copy of the data, so deleting one frees nothing.
    seen, out = set(), []
    for p in paths:
        st = p.stat()
        key = (st.st_dev, st.st_ino)
        if key not in seen:
            seen.add(key)
            out.append(p)
    return out


def find_duplicates(root: Path, min_size: int):
    by_size = defaultdict(list)
    for path, st in iter_files(root, min_size):
        by_size[st.st_size].append(path)

    by_hash = defaultdict(list)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue                                 # a unique size cannot be a duplicate
        for path in paths:
            try:
                by_hash[sha256(path)].append(path)
            except OSError:
                continue

    groups = []
    for paths in by_hash.values():
        distinct = distinct_inodes(paths)
        if len(distinct) > 1:
            groups.append(sorted(distinct))
    return groups


def main():
    ap = argparse.ArgumentParser(description="Find duplicate files by content.")
    ap.add_argument("root", type=Path, help="directory to scan")
    ap.add_argument("--min-size", type=int, default=1, help="ignore files smaller than this many bytes")
    ap.add_argument("--delete", action="store_true", help="delete every copy except the first in each group")
    args = ap.parse_args()

    groups = find_duplicates(args.root.expanduser().resolve(), args.min_size)
    reclaimable = 0
    for group in groups:
        size = group[0].stat().st_size
        reclaimable += size * (len(group) - 1)
        print(f"\n{len(group)} copies, {size} bytes each:")
        for p in group:
            print("   ", p)
        if args.delete:
            for p in group[1:]:
                p.unlink()
                print("    deleted", p)
    print(f"\n{len(groups)} groups, {reclaimable / 1e6:.1f} MB reclaimable")


if __name__ == "__main__":
    main()
```

Run a dry scan first with `python3 dupes.py ~/Downloads`, and only add `--delete` after reviewing the groups.

Plan: a small state machine. Rooms form a map keyed by id, each exit may require an item, and a command parser turns each line into a verb and an object. Shortcuts such as n and s map onto the same handlers. The game state is only the current room, the inventory, and a finished flag, so it stays easy to test.

```cpp
// adventure.cpp
// Build: g++ -std=c++17 -Wall -Wextra adventure.cpp -o adventure
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <string>

class Game {
public:
    Game() {
        rooms_ = {
            {"hall", {"Entrance Hall", "A dusty hall. A staircase climbs into the dark.",
                      {{"north", {"library", ""}}, {"up", {"tower", "key"}}},
                      {"lamp"}}},
            {"library", {"Library", "Shelves of crumbling books. Something glints under a desk.",
                         {{"south", {"hall", ""}}},
                         {"key"}}},
            {"tower", {"Tower Top", "Wind howls through broken shutters. A chest sits in the corner.",
                       {{"down", {"hall", ""}}},
                       {"treasure"}}},
        };
        location_ = "hall";
    }

    void run() {
        std::cout << "Type 'help' for commands.\n";
        describe();
        std::string line;
        while (!over_) {
            std::cout << "\n> ";
            if (!std::getline(std::cin, line)) break;
            handle(line);
        }
    }

private:
    struct Exit { std::string to, needs; };     // needs is empty for an open exit
    struct Room {
        std::string title, description;
        std::map<std::string, Exit> exits;
        std::set<std::string> items;
    };

    std::map<std::string, Room> rooms_;
    std::string location_;
    std::set<std::string> inventory_;
    bool over_ = false;

    void describe() const {
        const Room& room = rooms_.at(location_);
        std::cout << "\n== " << room.title << " ==\n" << room.description << '\n';
        if (!room.items.empty()) {
            std::cout << "You see:";
            for (const auto& item : room.items) std::cout << ' ' << item;
            std::cout << '\n';
        }
        std::cout << "Exits:";
        for (const auto& entry : room.exits) std::cout << ' ' << entry.first;
        std::cout << '\n';
    }

    void handle(const std::string& line) {
        std::istringstream in(line);
        std::string verb, object;
        in >> verb;
        std::getline(in >> std::ws, object);
        if (verb.empty()) return;

        static const std::map<std::string, std::string> shortcuts = {
            {"n", "north"}, {"s", "south"}, {"e", "east"}, {"w", "west"}, {"u", "up"}, {"d", "down"}};
        if (auto it = shortcuts.find(verb); it != shortcuts.end()) verb = it->second;

        if (verb == "go") go(object);
        else if (verb == "north" || verb == "south" || verb == "east" || verb == "west" ||
                 verb == "up" || verb == "down") go(verb);
        else if (verb == "look") describe();
        else if (verb == "take") take(object);
        else if (verb == "inventory" || verb == "i") showInventory();
        else if (verb == "help") std::cout << "Commands: look, go <dir>, n/s/e/w/u/d, take <item>, inventory, quit\n";
        else if (verb == "quit") over_ = true;
        else std::cout << "I don't understand '" << verb << "'.\n";
    }

    void go(const std::string& dir) {
        const Room& here = rooms_.at(location_);
        auto it = here.exits.find(dir);
        if (it == here.exits.end()) { std::cout << "You can't go that way.\n"; return; }
        const Exit& link = it->second;
        if (!link.needs.empty() && inventory_.count(link.needs) == 0) {
            std::cout << "The way is blocked. You need the " << link.needs << ".\n";
            return;
        }
        location_ = link.to;
        describe();
    }

    void take(const std::string& item) {
        if (item.empty()) { std::cout << "Take what?\n"; return; }
        Room& here = rooms_.at(location_);
        if (here.items.erase(item) == 0) { std::cout << "There is no " << item << " here.\n"; return; }
        inventory_.insert(item);
        std::cout << "Taken: " << item << ".\n";
        if (item == "treasure") { std::cout << "You win!\n"; over_ = true; }
    }

    void showInventory() const {
        if (inventory_.empty()) { std::cout << "You carry nothing.\n"; return; }
        std::cout << "You carry:";
        for (const auto& item : inventory_) std::cout << ' ' << item;
        std::cout << '\n';
    }
};

int main() {
    Game().run();
}
```

Try `take lamp`, `n`, `take key`, `s`, `u`, `take treasure`. To grow the game, add rooms and items to the initializer, or load the map from a file so that content and code are separate.

Plan: a .NET 8 worker service. Each job runs on its own loop driven by PeriodicTimer. Failures are retried with exponential backoff, and the stopping token flows into every await, so shutdown is clean. Create the project with `dotnet new worker -n JobRunner`, then replace the template files with these two.

**Jobs.cs**
```csharp
public sealed record Job(string Name, TimeSpan Interval, Func<CancellationToken, Task> Work);

public sealed class JobRegistry
{
    private static readonly Random Rng = new();

    public IReadOnlyList<Job> Jobs { get; } =
    [
        new("heartbeat", TimeSpan.FromSeconds(5), _ =>
        {
            Console.WriteLine($"alive {DateTime.Now:T}");
            return Task.CompletedTask;
        }),
        new("flaky-sync", TimeSpan.FromSeconds(10), SyncAsync),
    ];

    private static async Task SyncAsync(CancellationToken ct)
    {
        await Task.Delay(300, ct);
        if (Rng.NextDouble() < 0.5) throw new IOException("remote unavailable");
        Console.WriteLine("sync complete");
    }
}
```

**JobRunnerService.cs**
```csharp
public sealed class JobRunnerService(JobRegistry registry, ILogger<JobRunnerService> log) : BackgroundService
{
    private const int MaxAttempts = 3;

    protected override Task ExecuteAsync(CancellationToken stoppingToken) =>
        Task.WhenAll(registry.Jobs.Select(job => RunLoopAsync(job, stoppingToken)));

    private async Task RunLoopAsync(Job job, CancellationToken ct)
    {
        using var timer = new PeriodicTimer(job.Interval);
        while (await timer.WaitForNextTickAsync(ct))
            await RunWithRetryAsync(job, ct);
    }

    private async Task RunWithRetryAsync(Job job, CancellationToken ct)
    {
        for (int attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            try
            {
                await job.Work(ct);
                log.LogInformation("{Job} succeeded on attempt {Attempt}", job.Name, attempt);
                return;
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                log.LogWarning(ex, "{Job} failed on attempt {Attempt}", job.Name, attempt);
                if (attempt < MaxAttempts)
                    await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, attempt)), ct);
            }
        }
        log.LogError("{Job} gave up after {Max} attempts", job.Name, MaxAttempts);
    }
}
```

**Program.cs**
```csharp
var builder = Host.CreateApplicationBuilder(args);
builder.Services.AddSingleton<JobRegistry>();
builder.Services.AddHostedService<JobRunnerService>();
builder.Build().Run();
```

Run with `dotnet run`, and stop with Ctrl+C. To add a job, add one `new Job(...)` entry. For jobs that must run exactly once across several server instances, add a distributed lock, because each instance runs its own timers.

Plan: a parallel regex search. Directory traversal is single-threaded through walkdir, while reading and matching run on a rayon thread pool. Binary or non-UTF-8 files are skipped, so their bytes never reach the terminal. Matches go to stdout as path:line:text, and the summary goes to stderr, so the output pipes cleanly.

**Cargo.toml** (dependencies)
```toml
[dependencies]
clap = { version = "4", features = ["derive"] }
rayon = "1"
regex = "1"
walkdir = "2"
```

**src/main.rs**
```rust
use clap::Parser;
use rayon::prelude::*;
use regex::Regex;
use std::fs;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

/// A small parallel grep: regex search across a directory tree.
#[derive(Parser)]
struct Args {
    /// Regular expression to search for
    pattern: String,
    /// Directory to search
    #[arg(default_value = ".")]
    root: PathBuf,
    /// Case-insensitive matching
    #[arg(short, long)]
    ignore_case: bool,
    /// Only search files with this extension, e.g. rs
    #[arg(short, long)]
    ext: Option<String>,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    let pattern = if args.ignore_case {
        format!("(?i){}", args.pattern)
    } else {
        args.pattern.clone()
    };
    let re = Regex::new(&pattern)?;

    let files: Vec<PathBuf> = WalkDir::new(&args.root)
        .into_iter()
        .filter_map(Result::ok)                       // skip unreadable entries
        .filter(|e| e.file_type().is_file())
        .filter(|e| match &args.ext {
            Some(ext) => e.path().extension().is_some_and(|x| x == ext.as_str()),
            None => true,
        })
        .map(|e| e.into_path())
        .collect();

    // Files are independent, so they are searched in parallel across all cores.
    let total: usize = files.par_iter().map(|path| search_file(path, &re)).sum();
    eprintln!("{total} matching lines in {} files", files.len());
    Ok(())
}

fn search_file(path: &Path, re: &Regex) -> usize {
    let Ok(text) = fs::read_to_string(path) else {
        return 0;                                    // binary or unreadable: skip
    };
    let mut hits = 0;
    for (n, line) in text.lines().enumerate() {
        if re.is_match(line) {
            hits += 1;
            println!("{}:{}: {}", path.display(), n + 1, line.trim_end());
        }
    }
    hits
}
```

Build with `cargo build --release` and run `./target/release/pgrep "fn \w+" src --ext rs`. The per-file parallelism helps most on large trees of small files. For one huge file, split the input into chunks instead.
